  "internals.faq.bard.what-subclasses-can-a-bard-choose": {
    "href": "/faq/bard/what-subclasses-can-a-bard-choose",
    "external": false,
    "title": "D&D Portal - What subclasses can a Bard choose?",
    "subTitle": "Bard FAQ",
    "description": "A Bard's subclass is called a Bard College and is chosen at 3rd level in the 2014 rules. Official pre-2024 Fifth Edition options include College of Lore, Valor, Glamour, Swords, Whispers, Eloquence, Creation, and Spirits. Each keeps the Bard's core spellcasting, Bardic Inspiration, skills, and Magical Secrets while changing how the class specialises.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What subclasses can a Bard choose?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
