  "internals.faq.artificer.what-is-an-artificer-in-dnd": {
    "href": "/faq/artificer/what-is-an-artificer-in-dnd",
    "external": false,
    "title": "D&D Portal - What is an Artificer in D&D?",
    "subTitle": "Artificer FAQ",
    "description": "An Artificer is an Intelligence-based half-caster who combines magic, tools, crafted equipment, and magical infusions. Rather than relying only on spells, Artificers turn ordinary objects into magical resources, support the party with flexible utility, and specialise at 3rd level as an Alchemist, Armorer, Artillerist, or Battle Smith.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is an Artificer in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.artificer.how-do-you-play-an-artificer": {
    "href": "/faq/artificer/how-do-you-play-an-artificer",
    "external": false,
    "title": "D&D Portal - How do you play an Artificer?",
    "subTitle": "Artificer FAQ",
    "description": "Play an Artificer by planning ahead: keep Intelligence high, prepare spells for the expected adventure, choose infusions that benefit the whole party, and use tools and Flash of Genius to solve problems that raw damage cannot. Your Specialist determines whether you lean toward support, armor, ranged magical damage, or weapon combat.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you play an Artificer?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.artificer.what-ability-scores-are-best-for-an-artificer": {
    "href": "/faq/artificer/what-ability-scores-are-best-for-an-artificer",
    "external": false,
    "title": "D&D Portal - What ability scores are best for an Artificer?",
    "subTitle": "Artificer FAQ",
    "description": "Intelligence is normally the Artificer's highest ability score because it powers spellcasting, prepared spells, Flash of Genius, and many Specialist features. Constitution is usually the next priority for hit points and concentration, while Dexterity improves initiative and defense. The exact secondary priorities depend on the chosen Specialist.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What ability scores are best for an Artificer?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.artificer.what-are-the-main-artificer-class-features": {
    "href": "/faq/artificer/what-are-the-main-artificer-class-features",
    "external": false,
    "title": "D&D Portal - What are the main Artificer class features?",
    "subTitle": "Artificer FAQ",
    "description": "The Artificer's main features are Magical Tinkering, prepared Spellcasting, Infuse Item, an Artificer Specialist, The Right Tool for the Job, Tool Expertise, Flash of Genius, Spell-Storing Item, increasingly powerful magic-item attunement, and Soul of Artifice. Together they make the class a flexible magical inventor rather than a conventional caster.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Artificer class features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.artificer.what-subclasses-can-an-artificer-choose": {
    "href": "/faq/artificer/what-subclasses-can-an-artificer-choose",
    "external": false,
    "title": "D&D Portal - What subclasses can an Artificer choose?",
    "subTitle": "Artificer FAQ",
    "description": "The pre-2024 Artificer has four main published Specialists: Alchemist, Armorer, Artillerist, and Battle Smith. The choice is made at 3rd level and strongly changes the class's role, from support and alchemy to magical armor, arcane artillery, or weapon combat with a Steel Defender.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What subclasses can an Artificer choose?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
