  "internals.faq.blood-hunter.what-is-a-blood-hunter-in-dnd": {
    "href": "/faq/blood-hunter/what-is-a-blood-hunter-in-dnd",
    "external": false,
    "title": "D&D Portal - What is a Blood Hunter in D&D?",
    "subTitle": "Blood Hunter FAQ",
    "description": "A Blood Hunter is a d10 martial monster-hunter from Critical Role that uses hemocraft—magic powered by the hunter's own vitality—to enhance weapons, invoke blood curses, and pursue supernatural enemies. Blood Hunters normally fight with Strength or Dexterity, use Intelligence or Wisdom for Hemocraft, gain Crimson Rite at 2nd level, and join a Blood Hunter Order at 3rd level.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is a Blood Hunter in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.blood-hunter.how-do-you-play-a-blood-hunter": {
    "href": "/faq/blood-hunter/how-do-you-play-a-blood-hunter",
    "external": false,
    "title": "D&D Portal - How do you play a Blood Hunter?",
    "subTitle": "Blood Hunter FAQ",
    "description": "Play a Blood Hunter by choosing a clear Strength- or Dexterity-based weapon plan, keeping your Hemocraft ability useful, and treating self-damage as a real resource cost. Activate Crimson Rite when the expected value is worth the hit-point loss, amplify Blood Curses only when the stronger effect matters, and use Brands and monster knowledge to keep priority targets under pressure.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you play a Blood Hunter?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.blood-hunter.what-ability-scores-are-best-for-a-blood-hunter": {
    "href": "/faq/blood-hunter/what-ability-scores-are-best-for-a-blood-hunter",
    "external": false,
    "title": "D&D Portal - What ability scores are best for a Blood Hunter?",
    "subTitle": "Blood Hunter FAQ",
    "description": "A Blood Hunter normally prioritises Strength or Dexterity for weapon attacks, then Constitution because the class spends its own hit points, and Intelligence or Wisdom for Hemocraft features. The current class allows Intelligence or Wisdom to serve as the Hemocraft modifier. The exact order depends on whether the character is melee, ranged, Order-focused, or more dependent on saving-throw features.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What ability scores are best for a Blood Hunter?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.blood-hunter.what-are-the-main-blood-hunter-class-features": {
    "href": "/faq/blood-hunter/what-are-the-main-blood-hunter-class-features",
    "external": false,
    "title": "D&D Portal - What are the main Blood Hunter class features?",
    "subTitle": "Blood Hunter FAQ",
    "description": "The Blood Hunter's main features are Hunter's Bane, Blood Maledict, Fighting Style, Crimson Rite, a Blood Hunter Order, Extra Attack, Brand of Castigation, Grim Psychometry, Dark Augmentation, Brand of Tethering, Hardened Soul, and Sanguine Mastery. The Hemocraft die scales from d4 to d10 and is used by several class mechanics.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Blood Hunter class features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.blood-hunter.what-subclasses-can-a-blood-hunter-choose": {
    "href": "/faq/blood-hunter/what-subclasses-can-a-blood-hunter-choose",
    "external": false,
    "title": "D&D Portal - What subclasses can a Blood Hunter choose?",
    "subTitle": "Blood Hunter FAQ",
    "description": "A Blood Hunter chooses one of four Blood Hunter Orders at 3rd level: Order of the Ghostslayer, Order of the Lycan, Order of the Mutant, or Order of the Profane Soul. Ghostslayer specialises in undead and hemocraft, Lycan uses a controlled hybrid transformation, Mutant uses alchemical mutagens with benefits and drawbacks, and Profane Soul combines Blood Hunter martial abilities with limited patron-based spellcasting.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What subclasses can a Blood Hunter choose?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
