  "internals.faq.cleric.what-is-a-cleric-in-dnd": {
    "href": "/faq/cleric/what-is-a-cleric-in-dnd",
    "external": false,
    "title": "D&D Portal - What is a Cleric in D&D?",
    "subTitle": "Cleric FAQ",
    "description": "A Cleric is a Wisdom-based full spellcaster who channels divine power through prepared spells, a Divine Domain, and Channel Divinity. Clerics use a d8 Hit Die, wear light or medium armor and shields by default, and can support, heal, control, defend, or deal damage depending on their prepared spells and Domain. A Cleric chooses a Divine Domain at 1st level in the 2014 rules.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is a Cleric in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.cleric.how-do-you-play-a-cleric": {
    "href": "/faq/cleric/how-do-you-play-a-cleric",
    "external": false,
    "title": "D&D Portal - How do you play a Cleric?",
    "subTitle": "Cleric FAQ",
    "description": "Play a Cleric by keeping Wisdom high, preparing spells for the expected day, and deciding which role matters most in each encounter. Use concentration for high-impact buffs or control, Channel Divinity when its effect changes the fight, and healing when it prevents defeat rather than treating every turn as a healing turn. Your Divine Domain determines whether you lean more toward restoration, defense, offense, utility, or martial play.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you play a Cleric?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.cleric.what-ability-scores-are-best-for-a-cleric": {
    "href": "/faq/cleric/what-ability-scores-are-best-for-a-cleric",
    "external": false,
    "title": "D&D Portal - What ability scores are best for a Cleric?",
    "subTitle": "Cleric FAQ",
    "description": "Wisdom is normally the Cleric's highest ability score because it powers spellcasting, prepared spells, and many Domain features. Constitution is usually the next priority for hit points and concentration. Strength or Dexterity depends on armor and weapon choices: heavy-armored or melee Clerics may value Strength, while medium-armored Clerics often benefit from Dexterity. The 2014 multiclassing prerequisite is Wisdom 13.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What ability scores are best for a Cleric?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.cleric.what-are-the-main-cleric-class-features": {
    "href": "/faq/cleric/what-are-the-main-cleric-class-features",
    "external": false,
    "title": "D&D Portal - What are the main Cleric class features?",
    "subTitle": "Cleric FAQ",
    "description": "The 2014 Cleric's main features are prepared Spellcasting, a Divine Domain, Channel Divinity, Turn Undead, Destroy Undead, and Divine Intervention. Domain features arrive throughout the class progression and provide always-prepared Domain Spells plus specialised Channel Divinity and later abilities. Together these systems make the Cleric a durable and highly adaptable divine full caster.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Cleric class features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.cleric.what-subclasses-can-a-cleric-choose": {
    "href": "/faq/cleric/what-subclasses-can-a-cleric-choose",
    "external": false,
    "title": "D&D Portal - What subclasses can a Cleric choose?",
    "subTitle": "Cleric FAQ",
    "description": "A Cleric's subclass is called a Divine Domain and is chosen at 1st level in the 2014 rules. Major official pre-2024 Fifth Edition options include Arcana, Death, Forge, Grave, Knowledge, Life, Light, Nature, Order, Peace, Tempest, Trickery, Twilight, and War. Individual campaign availability can still restrict which Domains are selectable.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What subclasses can a Cleric choose?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
