  "internals.faq.druid.what-is-a-druid-in-dnd": {
    "href": "/faq/druid/what-is-a-druid-in-dnd",
    "external": false,
    "title": "D&D Portal - What is a Druid in D&D?",
    "subTitle": "Druid FAQ",
    "description": "A Druid is a Wisdom-based prepared full spellcaster connected to nature, primal magic, and shapeshifting. Druids use a d8 Hit Die, gain Wild Shape at 2nd level, choose a Druid Circle at 2nd level, and can contribute through healing, control, summoning, elemental magic, exploration, and animal forms rather than being limited to one combat role.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is a Druid in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.druid.how-do-you-play-a-druid": {
    "href": "/faq/druid/how-do-you-play-a-druid",
    "external": false,
    "title": "D&D Portal - How do you play a Druid?",
    "subTitle": "Druid FAQ",
    "description": "Play a Druid by keeping Wisdom high, preparing spells for the expected environment, and treating Wild Shape as a flexible exploration and combat resource rather than only an animal attack form. Concentration, positioning, and Druid Circle matter heavily: a Moon Druid may fight in beast form, while other Druids often get more value from control, summoning, healing, utility, or Circle-specific forms.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you play a Druid?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.druid.what-ability-scores-are-best-for-a-druid": {
    "href": "/faq/druid/what-ability-scores-are-best-for-a-druid",
    "external": false,
    "title": "D&D Portal - What ability scores are best for a Druid?",
    "subTitle": "Druid FAQ",
    "description": "Wisdom is normally the Druid's highest ability score because it powers Druid spellcasting and prepared spells. Constitution is usually the next priority for hit points and concentration, while Dexterity helps initiative and Armor Class. Strength is often less important because many Druids fight through spells or Wild Shape. The 2014 multiclassing prerequisite is Wisdom 13.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What ability scores are best for a Druid?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.druid.what-are-the-main-druid-class-features": {
    "href": "/faq/druid/what-are-the-main-druid-class-features",
    "external": false,
    "title": "D&D Portal - What are the main Druid class features?",
    "subTitle": "Druid FAQ",
    "description": "The 2014 Druid's main features are Druidic, prepared Spellcasting, Wild Shape, a Druid Circle, Wild Shape improvements, Timeless Body, Beast Spells, and Archdruid. Spellcasting provides broad healing, control, summoning, elemental, and exploration options, while Wild Shape provides transformation and utility that becomes more capable as the Druid gains levels.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Druid class features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.druid.what-subclasses-can-a-druid-choose": {
    "href": "/faq/druid/what-subclasses-can-a-druid-choose",
    "external": false,
    "title": "D&D Portal - What subclasses can a Druid choose?",
    "subTitle": "Druid FAQ",
    "description": "A Druid's subclass is called a Druid Circle and is chosen at 2nd level in the 2014 rules. Major official pre-2024 Fifth Edition options include Circle of the Land, Moon, Dreams, Shepherd, Spores, Stars, and Wildfire. Each keeps the Druid's prepared spellcasting and Wild Shape while changing whether the class emphasises casting, combat transformation, support, summons, fungal power, cosmic forms, or a wildfire spirit.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What subclasses can a Druid choose?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
