  "internals.faq.monk.what-is-a-monk-in-dnd": {
    "href": "/faq/monk/what-is-a-monk-in-dnd",
    "external": false,
    "title": "D&D Portal - What is a Monk in D&D?",
    "subTitle": "Monk FAQ",
    "description": "A Monk is a Dexterity- and Wisdom-based martial class built around unarmored combat, Martial Arts, ki, speed, and battlefield mobility. Monks use a d8 Hit Die, gain Unarmored Defense and Martial Arts at 1st level, unlock ki and increased movement at 2nd level, and choose a Monastic Tradition at 3rd level. They are mobile skirmishers rather than heavily armored front-line tanks.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is a Monk in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.monk.how-do-you-play-a-monk": {
    "href": "/faq/monk/how-do-you-play-a-monk",
    "external": false,
    "title": "D&D Portal - How do you play a Monk?",
    "subTitle": "Monk FAQ",
    "description": "Play a Monk as a mobile skirmisher: keep Dexterity and Wisdom high, use movement to reach useful targets, and spend ki according to the situation. Flurry of Blows increases offense, Patient Defense improves survival, Step of the Wind improves mobility, and Stunning Strike can control a priority enemy. Avoid treating every ki point as automatic damage or standing still like a heavily armored Fighter.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you play a Monk?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.monk.what-ability-scores-are-best-for-a-monk": {
    "href": "/faq/monk/what-ability-scores-are-best-for-a-monk",
    "external": false,
    "title": "D&D Portal - What ability scores are best for a Monk?",
    "subTitle": "Monk FAQ",
    "description": "Dexterity is normally the Monk's highest ability score because it powers most Martial Arts attacks and improves Armor Class and initiative. Wisdom is usually the second priority because it also improves Unarmored Defense and sets the saving throw DC for many ki features. Constitution supports hit points. In the 2014 multiclassing rules, a Monk requires Dexterity 13 and Wisdom 13.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What ability scores are best for a Monk?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.monk.what-are-the-main-monk-class-features": {
    "href": "/faq/monk/what-are-the-main-monk-class-features",
    "external": false,
    "title": "D&D Portal - What are the main Monk class features?",
    "subTitle": "Monk FAQ",
    "description": "The 2014 Monk's main features are Unarmored Defense, Martial Arts, ki, Unarmored Movement, a Monastic Tradition, Deflect Missiles, Slow Fall, Extra Attack, Stunning Strike, Ki-Empowered Strikes, Evasion, Stillness of Mind, Purity of Body, Diamond Soul, Empty Body, and Perfect Self. Together they create a fast martial class that spends ki on offense, defense, movement, and control.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Monk class features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.monk.what-subclasses-can-a-monk-choose": {
    "href": "/faq/monk/what-subclasses-can-a-monk-choose",
    "external": false,
    "title": "D&D Portal - What subclasses can a Monk choose?",
    "subTitle": "Monk FAQ",
    "description": "A Monk's subclass is called a Monastic Tradition and is chosen at 3rd level in the 2014 rules. Major official pre-2024 Fifth Edition options include Way of the Open Hand, Shadow, Four Elements, Long Death, Sun Soul, Drunken Master, Kensei, Mercy, Astral Self, and Ascendant Dragon. Each keeps the Monk's Martial Arts, ki, and mobility while changing how those resources are used.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What subclasses can a Monk choose?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
