  "internals.faq.paladin.what-is-a-paladin-in-dnd": {
    "href": "/faq/paladin/what-is-a-paladin-in-dnd",
    "external": false,
    "title": "D&D Portal - What is a Paladin in D&D?",
    "subTitle": "Paladin FAQ",
    "description": "A Paladin is a Strength- and Charisma-focused martial half-caster built around heavy armor, weapons, healing, Divine Smite, protective auras, and a Sacred Oath. Paladins use a d10 Hit Die, gain Spellcasting and Divine Smite at 2nd level, choose a Sacred Oath at 3rd level, and become exceptionally strong at protecting nearby allies through Aura of Protection from 6th level onward.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is a Paladin in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.paladin.how-do-you-play-a-paladin": {
    "href": "/faq/paladin/how-do-you-play-a-paladin",
    "external": false,
    "title": "D&D Portal - How do you play a Paladin?",
    "subTitle": "Paladin FAQ",
    "description": "Play a Paladin as a front-line protector and burst-damage martial character. Use Strength for most melee builds, keep Charisma strong for spells and Aura of Protection, and treat spell slots as a flexible resource that can become spells or Divine Smites. Do not spend every slot on the first target you hit: save burst damage for important enemies and use your auras, Lay on Hands, and concentration spells to keep the party functioning.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you play a Paladin?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.paladin.what-ability-scores-are-best-for-a-paladin": {
    "href": "/faq/paladin/what-ability-scores-are-best-for-a-paladin",
    "external": false,
    "title": "D&D Portal - What ability scores are best for a Paladin?",
    "subTitle": "Paladin FAQ",
    "description": "Strength and Charisma are the Paladin's main ability scores in the 2014 rules. Strength normally powers melee attacks and supports heavy armor, while Charisma powers Paladin spellcasting and Aura of Protection. Constitution is usually the next priority for hit points and concentration. The 2014 multiclassing prerequisites require both Strength 13 and Charisma 13.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What ability scores are best for a Paladin?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.paladin.what-are-the-main-paladin-class-features": {
    "href": "/faq/paladin/what-are-the-main-paladin-class-features",
    "external": false,
    "title": "D&D Portal - What are the main Paladin class features?",
    "subTitle": "Paladin FAQ",
    "description": "The 2014 Paladin's main features are Divine Sense, Lay on Hands, Fighting Style, Spellcasting, Divine Smite, Divine Health, a Sacred Oath, Extra Attack, Aura of Protection, Aura of Courage, Improved Divine Smite, Cleansing Touch, and expanded aura range. These features combine martial offense, healing, burst damage, spellcasting, and unusually strong party-wide saving throw protection.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Paladin class features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.paladin.what-subclasses-can-a-paladin-choose": {
    "href": "/faq/paladin/what-subclasses-can-a-paladin-choose",
    "external": false,
    "title": "D&D Portal - What subclasses can a Paladin choose?",
    "subTitle": "Paladin FAQ",
    "description": "A Paladin's subclass is called a Sacred Oath and is chosen at 3rd level in the 2014 rules. Major official pre-2024 Fifth Edition options include Oath of Devotion, Ancients, Vengeance, Crown, Conquest, Redemption, Glory, and Watchers, while Oathbreaker is a Dungeon Master's Guide option with a special villainous or fallen-paladin context. Each Oath adds Oath Spells, Channel Divinity, an aura or equivalent feature, and later subclass abilities.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What subclasses can a Paladin choose?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
