  "internals.faq.pugilist.what-is-a-pugilist-in-dnd": {
    "href": "/faq/pugilist/what-is-a-pugilist-in-dnd",
    "external": false,
    "title": "D&D Portal - What is a Pugilist in D&D?",
    "subTitle": "Pugilist FAQ",
    "description": "The Pugilist version used by D&D Portal is a Strength- and Constitution-focused d8 martial class built around Fisticuffs, Iron Chin, Moxie, improvised or pugilist weapons, and a never-stay-down style of fighting. It gains Moxie at 2nd level, Bloodied but Unbowed and a Fight Club at 3rd level, Extra Attack and Haymaker at 5th level, and increasingly strong durability features at higher levels. This is not the later d10 Pugilist (2024) version.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is a Pugilist in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.pugilist.how-do-you-play-a-pugilist": {
    "href": "/faq/pugilist/how-do-you-play-a-pugilist",
    "external": false,
    "title": "D&D Portal - How do you play a Pugilist?",
    "subTitle": "Pugilist FAQ",
    "description": "Play a Pugilist by keeping Strength and Constitution high, using Fisticuffs as your reliable baseline, and spending Moxie according to what the round needs. Brace Up improves durability, The Old One-Two increases offense, and Stick and Move improves mobility or control. Bloodied but Unbowed can restore momentum after heavy damage, while Haymaker is a deliberate accuracy-for-damage tradeoff rather than an automatic attack mode.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you play a Pugilist?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.pugilist.what-ability-scores-are-best-for-a-pugilist": {
    "href": "/faq/pugilist/what-ability-scores-are-best-for-a-pugilist",
    "external": false,
    "title": "D&D Portal - What ability scores are best for a Pugilist?",
    "subTitle": "Pugilist FAQ",
    "description": "Strength is normally the Pugilist's highest ability score and Constitution is the second priority. Strength powers the class's close-range attacks, while Constitution increases hit points and can replace Dexterity when calculating Armor Class through Iron Chin. Some Fight Clubs make Charisma, Wisdom, or another secondary ability more valuable. This version requires Strength 13 and Constitution 13 for multiclassing.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What ability scores are best for a Pugilist?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.pugilist.what-are-the-main-pugilist-class-features": {
    "href": "/faq/pugilist/what-are-the-main-pugilist-class-features",
    "external": false,
    "title": "D&D Portal - What are the main Pugilist class features?",
    "subTitle": "Pugilist FAQ",
    "description": "This Pugilist's main features are Fisticuffs, Iron Chin, Moxie, Street Smart, Bloodied but Unbowed, a Fight Club, Dig Deep, Extra Attack, Haymaker, Moxie-Fueled Fists, Fancy Footwork, Shake It Off, Down But Not Out, School of Hard Knocks, Rabble Rouser, Unbreakable, Herculean, Fighting Spirit, and Peak Physical Condition. Moxie returns after a short or long rest.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Pugilist class features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.pugilist.what-fight-clubs-can-a-pugilist-choose": {
    "href": "/faq/pugilist/what-fight-clubs-can-a-pugilist-choose",
    "external": false,
    "title": "D&D Portal - What Fight Clubs can a Pugilist choose?",
    "subTitle": "Pugilist FAQ",
    "description": "The D&D Portal Pugilist chooses one of six Fight Clubs at 3rd level: **Arena Royale, Bloodhound Bruisers, Dog & Hound, Piss & Vinegar, The Squared Circle, or The Sweet Science**. Arena Royale is a performer-gladiator, Bloodhound Bruisers is an urban investigator, Dog & Hound fights with a canine companion, Piss & Vinegar uses provocation and dirty tricks, Squared Circle specialises in grappling, and Sweet Science specialises in technical boxing and counters.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What Fight Clubs can a Pugilist choose?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
