  "internals.faq.ranger.what-is-a-ranger-in-dnd": {
    "href": "/faq/ranger/what-is-a-ranger-in-dnd",
    "external": false,
    "title": "D&D Portal - What is a Ranger in D&D?",
    "subTitle": "Ranger FAQ",
    "description": "A Ranger is a d10 martial half-caster built around weapons, exploration, tracking, and Wisdom-based primal magic. In the 2014 rules, Rangers begin with Favored Enemy and Natural Explorer, gain Fighting Style and Spellcasting at 2nd level, choose a Ranger Archetype at 3rd level, and gain Extra Attack at 5th level. Dexterity and Wisdom are the most common priorities, although Strength-based Rangers are possible.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is a Ranger in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.ranger.how-do-you-play-a-ranger": {
    "href": "/faq/ranger/how-do-you-play-a-ranger",
    "external": false,
    "title": "D&D Portal - How do you play a Ranger?",
    "subTitle": "Ranger FAQ",
    "description": "Play a Ranger by choosing a clear weapon style, keeping Dexterity or Strength high, and using Wisdom for spells and exploration skills. Use the Ranger's spells to improve positioning, tracking, control, healing, or weapon pressure rather than treating them as a separate full-caster system. Favored Enemy and Natural Explorer are the 2014 exploration features, while the Ranger Archetype determines the character's main specialist combat identity.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you play a Ranger?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.ranger.what-ability-scores-are-best-for-a-ranger": {
    "href": "/faq/ranger/what-ability-scores-are-best-for-a-ranger",
    "external": false,
    "title": "D&D Portal - What ability scores are best for a Ranger?",
    "subTitle": "Ranger FAQ",
    "description": "Dexterity and Wisdom are the most common Ranger ability priorities. Dexterity powers bows and finesse weapons and improves Armor Class and initiative, while Wisdom powers Ranger spellcasting and important exploration skills. Constitution is usually the next priority. Strength can replace Dexterity as the main attack ability for a melee build. The 2014 multiclassing prerequisites require Dexterity 13 and Wisdom 13.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What ability scores are best for a Ranger?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.ranger.what-are-the-main-ranger-class-features": {
    "href": "/faq/ranger/what-are-the-main-ranger-class-features",
    "external": false,
    "title": "D&D Portal - What are the main Ranger class features?",
    "subTitle": "Ranger FAQ",
    "description": "The 2014 Ranger's main features are Favored Enemy, Natural Explorer, Fighting Style, Wisdom-based Spellcasting, a Ranger Archetype, Primeval Awareness, Extra Attack, Land's Stride, Hide in Plain Sight, Vanish, Feral Senses, and Foe Slayer. The base class combines martial combat and exploration, while the Archetype supplies much of the Ranger's specialised combat identity.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Ranger class features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.ranger.what-subclasses-can-a-ranger-choose": {
    "href": "/faq/ranger/what-subclasses-can-a-ranger-choose",
    "external": false,
    "title": "D&D Portal - What subclasses can a Ranger choose?",
    "subTitle": "Ranger FAQ",
    "description": "A Ranger's subclass is called a Ranger Archetype and is chosen at 3rd level in the 2014 rules. Major official pre-2024 Fifth Edition options include Hunter, Beast Master, Gloom Stalker, Horizon Walker, Monster Slayer, Fey Wanderer, Swarmkeeper, and Drakewarden. Each keeps the Ranger's weapon combat and spellcasting while adding a different specialisation such as hunting techniques, a companion, ambushes, planar mobility, supernatural monster hunting, fey magic, a swarm, or a drake.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What subclasses can a Ranger choose?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
