  "internals.faq.sorcerer.what-is-a-sorcerer-in-dnd": {
    "href": "/faq/sorcerer/what-is-a-sorcerer-in-dnd",
    "external": false,
    "title": "D&D Portal - What is a Sorcerer in D&D?",
    "subTitle": "Sorcerer FAQ",
    "description": "A Sorcerer is a Charisma-based full spellcaster whose magic is innate rather than learned from a spellbook. Sorcerers use a d6 Hit Die, choose a Sorcerous Origin at 1st level, gain Sorcery Points through Font of Magic at 2nd level, and gain Metamagic at 3rd level. Their spell list is narrower in practice because they know relatively few spells, but Metamagic allows those spells to be modified in ways other casters cannot easily reproduce.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is a Sorcerer in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.sorcerer.how-do-you-play-a-sorcerer": {
    "href": "/faq/sorcerer/how-do-you-play-a-sorcerer",
    "external": false,
    "title": "D&D Portal - How do you play a Sorcerer?",
    "subTitle": "Sorcerer FAQ",
    "description": "Play a Sorcerer by choosing a compact spell list that works well with your Metamagic instead of trying to imitate a Wizard's breadth. Keep Charisma high, protect concentration, and spend Sorcery Points when modifying a spell meaningfully changes the encounter. Flexible Casting can trade between spell slots and Sorcery Points, but both are limited long-rest resources, so planning matters.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you play a Sorcerer?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.sorcerer.what-ability-scores-are-best-for-a-sorcerer": {
    "href": "/faq/sorcerer/what-ability-scores-are-best-for-a-sorcerer",
    "external": false,
    "title": "D&D Portal - What ability scores are best for a Sorcerer?",
    "subTitle": "Sorcerer FAQ",
    "description": "Charisma is normally the Sorcerer's highest ability score because it powers spell attacks and spell save DCs. Constitution is usually the second priority for hit points and concentration, especially because Sorcerers already have Constitution saving throw proficiency. Dexterity improves Armor Class and initiative. The 2014 Sorcerer multiclassing prerequisite is Charisma 13.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What ability scores are best for a Sorcerer?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.sorcerer.what-are-the-main-sorcerer-class-features": {
    "href": "/faq/sorcerer/what-are-the-main-sorcerer-class-features",
    "external": false,
    "title": "D&D Portal - What are the main Sorcerer class features?",
    "subTitle": "Sorcerer FAQ",
    "description": "The 2014 Sorcerer's main features are Spellcasting, a Sorcerous Origin, Font of Magic, Flexible Casting, Metamagic, additional Metamagic choices at higher levels, and Sorcerous Restoration. Spellcasting supplies the full-caster progression, Sorcery Points fuel the class's resource system, and Metamagic allows the Sorcerer to modify spells in unique ways.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Sorcerer class features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.sorcerer.what-subclasses-can-a-sorcerer-choose": {
    "href": "/faq/sorcerer/what-subclasses-can-a-sorcerer-choose",
    "external": false,
    "title": "D&D Portal - What subclasses can a Sorcerer choose?",
    "subTitle": "Sorcerer FAQ",
    "description": "A Sorcerer's subclass is called a Sorcerous Origin and is chosen at 1st level in the 2014 rules. Major official pre-2024 Fifth Edition options include Draconic Bloodline, Wild Magic, Divine Soul, Shadow Magic, Storm Sorcery, Aberrant Mind, Clockwork Soul, and Lunar Sorcery. Each keeps the Sorcerer's Charisma spellcasting and Metamagic while changing the source and specialist expression of the character's innate magic.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What subclasses can a Sorcerer choose?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
