  "internals.faq.warlock.what-is-a-warlock-in-dnd": {
    "href": "/faq/warlock/what-is-a-warlock-in-dnd",
    "external": false,
    "title": "D&D Portal - What is a Warlock in D&D?",
    "subTitle": "Warlock FAQ",
    "description": "A Warlock is a Charisma-based pact caster whose magic comes through a relationship with an Otherworldly Patron. Warlocks use a d8 Hit Die, gain Pact Magic and a Patron at 1st level, Eldritch Invocations at 2nd level, and a Pact Boon at 3rd level. Their spell slots are few but recover on a short or long rest in the 2014 rules, while Invocations and Mystic Arcanum provide additional magical abilities.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is a Warlock in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.warlock.how-do-you-play-a-warlock": {
    "href": "/faq/warlock/how-do-you-play-a-warlock",
    "external": false,
    "title": "D&D Portal - How do you play a Warlock?",
    "subTitle": "Warlock FAQ",
    "description": "Play a Warlock by treating Pact Magic slots as short-rest burst resources rather than trying to cast a leveled spell every round. Keep Charisma high, choose a reliable repeatable action such as an enhanced cantrip or Pact of the Blade weapon plan, and select Invocations that support the same build. Your Patron is the subclass, while the Pact Boon is a separate customization choice.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you play a Warlock?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.warlock.what-ability-scores-are-best-for-a-warlock": {
    "href": "/faq/warlock/what-ability-scores-are-best-for-a-warlock",
    "external": false,
    "title": "D&D Portal - What ability scores are best for a Warlock?",
    "subTitle": "Warlock FAQ",
    "description": "Charisma is normally the Warlock's highest ability score because it powers Pact Magic and many Invocations and Patron features. Constitution is usually the next priority for hit points and concentration, while Dexterity improves Armor Class and initiative in light armor. A weapon-focused build can create different priorities. The 2014 Warlock multiclassing prerequisite is Charisma 13.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What ability scores are best for a Warlock?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.warlock.what-are-the-main-warlock-class-features": {
    "href": "/faq/warlock/what-are-the-main-warlock-class-features",
    "external": false,
    "title": "D&D Portal - What are the main Warlock class features?",
    "subTitle": "Warlock FAQ",
    "description": "The 2014 Warlock's main features are an Otherworldly Patron, Pact Magic, Eldritch Invocations, a Pact Boon, Mystic Arcanum, and Eldritch Master. The Patron is the subclass, Pact Magic provides a small number of short-rest spell slots, Invocations provide modular magical abilities, and the Pact Boon adds a second major customization layer.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Warlock class features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.warlock.what-subclasses-can-a-warlock-choose": {
    "href": "/faq/warlock/what-subclasses-can-a-warlock-choose",
    "external": false,
    "title": "D&D Portal - What subclasses can a Warlock choose?",
    "subTitle": "Warlock FAQ",
    "description": "A Warlock's subclass is the Otherworldly Patron chosen at 1st level. Major official pre-2024 Fifth Edition Patrons include Archfey, Fiend, Great Old One, Undying, Celestial, Hexblade, Fathomless, Genie, and Undead. The Pact Boon chosen at 3rd level is a separate customization choice and should not be listed as a Warlock subclass.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What subclasses can a Warlock choose?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
