  "internals.faq.scholar.what-is-the-scholar-class-in-dnd": {
    "href": "/faq/scholar/what-is-the-scholar-class-in-dnd",
    "external": false,
    "title": "D&D Portal - What is the Scholar class in D&D?",
    "subTitle": "Scholar FAQ",
    "description": "The Scholar is a 10-level calling from *The Lord of the Rings Roleplaying*, published by Free League. It uses a d8 Hit Die, Intelligence and Wisdom as its primary abilities, light armor, Crafts, Rhymes of Lore, Hands of a Healer, Expertise, and a Scholar Tradition chosen at 3rd level. The two Traditions are Healing and Lore.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Scholar class in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.scholar.how-do-you-play-a-scholar": {
    "href": "/faq/scholar/how-do-you-play-a-scholar",
    "external": false,
    "title": "D&D Portal - How do you play a Scholar?",
    "subTitle": "Scholar FAQ",
    "description": "Play a Scholar by using Intelligence and Wisdom to solve problems before they become fights. Spend Rhymes of Lore on rolls that genuinely matter, use Cunning Mind to Help or make knowledge checks without giving up your action, and make short rests more valuable through Hands of a Healer. Choose Healing if you want stronger recovery and medical support, or Lore if you want stronger knowledge and Lore-die reliability.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you play a Scholar?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.scholar.what-ability-scores-are-best-for-a-scholar": {
    "href": "/faq/scholar/what-ability-scores-are-best-for-a-scholar",
    "external": false,
    "title": "D&D Portal - What ability scores are best for a Scholar?",
    "subTitle": "Scholar FAQ",
    "description": "Intelligence and Wisdom are the Scholar's primary abilities. Intelligence supports knowledge, investigation, Lore-focused features, and the Scholar's intellectual identity, while Wisdom supports healing, perception, and the Healing Tradition. Constitution is a useful third priority for durability. Under the multiple-calling rules, Scholar requires Intelligence 13.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What ability scores are best for a Scholar?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.scholar.what-are-the-main-scholar-class-features": {
    "href": "/faq/scholar/what-are-the-main-scholar-class-features",
    "external": false,
    "title": "D&D Portal - What are the main Scholar class features?",
    "subTitle": "Scholar FAQ",
    "description": "The Scholar's main features are Crafts, Rhymes of Lore, Unarmoured Defence, Cunning Mind, Hands of a Healer, Expertise, a Scholar Tradition, Virtues, Endless Rhymes, and Unfailing Rhymes. The calling progresses to 10th level, with Healing or Lore granting additional features at 3rd and 7th level.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Scholar class features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.scholar.what-subclasses-can-a-scholar-choose": {
    "href": "/faq/scholar/what-subclasses-can-a-scholar-choose",
    "external": false,
    "title": "D&D Portal - What subclasses can a Scholar choose?",
    "subTitle": "Scholar FAQ",
    "description": "A Scholar chooses one of two **Scholar Traditions** at 3rd level: **Healing** or **Lore**. Healing improves Medicine, short-rest recovery, and exhaustion relief. Lore improves Old Lore, the reliability of Lore dice, and later allows especially powerful successes on supported non-Medicine ability checks.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What subclasses can a Scholar choose?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
