  "internals.faq.gunslinger.what-is-a-gunslinger-in-dnd": {
    "href": "/faq/gunslinger/what-is-a-gunslinger-in-dnd",
    "external": false,
    "title": "D&D Portal - What is a Gunslinger in D&D?",
    "subTitle": "Gunslinger FAQ",
    "description": "The Gunslinger is a 20-level third-party firearm class from Mage Hand Press's *Valda's Spire of Secrets*. It uses a d8 Hit Die, Dexterity as its primary ability, Dexterity and Charisma saving throws, an expanded firearm system, powerful critical hits, and Risk Dice that power special maneuvers. It has six published subclasses: Deadeye, High Roller, Secret Agent, Spellslinger, Trick Shot, and White Hat.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is a Gunslinger in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.gunslinger.how-do-you-play-a-gunslinger": {
    "href": "/faq/gunslinger/how-do-you-play-a-gunslinger",
    "external": false,
    "title": "D&D Portal - How do you play a Gunslinger?",
    "subTitle": "Gunslinger FAQ",
    "description": "Play a Gunslinger by keeping Dexterity high, choosing a firearm loadout that matches your subclass, and treating Risk Dice as a limited tactical resource rather than spending every die immediately. Position for clean ranged attacks, look for ways to improve the reliability of critical-hit-focused attacks, and use Risk Dice maneuvers when their control, defense, mobility, or damage is worth the resource.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you play a Gunslinger?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.gunslinger.what-ability-scores-are-best-for-a-gunslinger": {
    "href": "/faq/gunslinger/what-ability-scores-are-best-for-a-gunslinger",
    "external": false,
    "title": "D&D Portal - What ability scores are best for a Gunslinger?",
    "subTitle": "Gunslinger FAQ",
    "description": "Dexterity is the Gunslinger's highest ability score because it powers the class's firearm attacks and supports Armor Class and initiative. Constitution is usually the second priority because the class uses a d8 Hit Die. Charisma fits the class's social identity and is one of its saving throw proficiencies, while a subclass such as Spellslinger can change secondary priorities.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What ability scores are best for a Gunslinger?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.gunslinger.what-are-the-main-gunslinger-class-features": {
    "href": "/faq/gunslinger/what-are-the-main-gunslinger-class-features",
    "external": false,
    "title": "D&D Portal - What are the main Gunslinger class features?",
    "subTitle": "Gunslinger FAQ",
    "description": "The Gunslinger's main systems are firearm-focused martial progression, quick-draw weapon handling, stronger critical-hit play, Risk Dice and their maneuvers, Extra Attack, and subclass features from one of six Gunslinger options. Risk Dice, maneuvers, and later critical-hit features use the progression defined by the class.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Gunslinger class features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.gunslinger.what-subclasses-can-a-gunslinger-choose": {
    "href": "/faq/gunslinger/what-subclasses-can-a-gunslinger-choose",
    "external": false,
    "title": "D&D Portal - What subclasses can a Gunslinger choose?",
    "subTitle": "Gunslinger FAQ",
    "description": "The Mage Hand Press Gunslinger has six published subclasses: **Deadeye, High Roller, Secret Agent, Spellslinger, Trick Shot, and White Hat**. They specialise the class in precision shooting, gambling and luck, covert operations, spell-and-gun play, technical trick shots, or heroic lawkeeper-style gunplay.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What subclasses can a Gunslinger choose?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
