  "internals.faq.illrigger.what-is-an-illrigger-in-dnd": {
    "href": "/faq/illrigger/what-is-an-illrigger-in-dnd",
    "external": false,
    "title": "D&D Portal - What is an Illrigger in D&D?",
    "subTitle": "Illrigger FAQ",
    "description": "An Illrigger is a d10 infernal martial class from MCDM's *The Illrigger Revised*. It uses Strength or Dexterity for weapon combat and Charisma for its infernal class mechanics. Illriggers place supernatural seals through Baleful Interdict, improve those seals with Interdict Boons, gain Extra Attack, and choose a Diabolic Contract at 3rd level: Architect of Ruin, Hellspeaker, Painkiller, Sanguine Knight, or Shadowmaster.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is an Illrigger in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.illrigger.how-do-you-play-an-illrigger": {
    "href": "/faq/illrigger/how-do-you-play-an-illrigger",
    "external": false,
    "title": "D&D Portal - How do you play an Illrigger?",
    "subTitle": "Illrigger FAQ",
    "description": "Play an Illrigger by choosing a coherent weapon plan, keeping Charisma strong, and treating seals as a tactical resource. Place Baleful Interdict on priority enemies, burn seals when the damage or Boon trigger matters, and preserve seals when a Contract or Interdict Boon may need them for a stronger effect. Your Diabolic Contract determines whether the character leans toward magic, manipulation, durability, blood-fuelled combat, or assassination.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you play an Illrigger?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.illrigger.what-ability-scores-are-best-for-an-illrigger": {
    "href": "/faq/illrigger/what-ability-scores-are-best-for-an-illrigger",
    "external": false,
    "title": "D&D Portal - What ability scores are best for an Illrigger?",
    "subTitle": "Illrigger FAQ",
    "description": "An Illrigger normally prioritises Strength or Dexterity for weapon combat and Charisma for Baleful Interdict, Invoke Hell, and many Contract features. Constitution is the usual next priority because the class operates close to danger and uses a d10 Hit Die. The Revised Illrigger's multiclass requirement is Charisma 13 plus Strength 13 or Dexterity 13.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What ability scores are best for an Illrigger?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.illrigger.what-are-the-main-illrigger-class-features": {
    "href": "/faq/illrigger/what-are-the-main-illrigger-class-features",
    "external": false,
    "title": "D&D Portal - What are the main Illrigger class features?",
    "subTitle": "Illrigger FAQ",
    "description": "The Revised Illrigger's main features are Baleful Interdict, Forked Tongue, Combat Mastery, Interdict Boons, a Diabolic Contract, Invoke Hell, Extra Attack, Infernal Conduit, Blood Price, Terrorizing Force, Superior Interdict, Infernal Majesty, and Master of Hell. The central gameplay loop is placing infernal seals and deciding whether to burn or expend them.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Illrigger class features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.illrigger.what-subclasses-can-an-illrigger-choose": {
    "href": "/faq/illrigger/what-subclasses-can-an-illrigger-choose",
    "external": false,
    "title": "D&D Portal - What subclasses can an Illrigger choose?",
    "subTitle": "Illrigger FAQ",
    "description": "The Revised Illrigger chooses a **Diabolic Contract** at 3rd level. The five Contracts are **Architect of Ruin, Hellspeaker, Painkiller, Sanguine Knight, and Shadowmaster**. Architect of Ruin adds spellcasting, Hellspeaker emphasises manipulation, Painkiller is the heavy battlefield enforcer, Sanguine Knight leans into blood and vitality, and Shadowmaster specialises in stealth and assassination.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What subclasses can an Illrigger choose?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
