  "internals.faq.warden.what-is-the-warden-class-in-dnd": {
    "href": "/faq/warden/what-is-the-warden-class-in-dnd",
    "external": false,
    "title": "D&D Portal - What is the Warden class in D&D?",
    "subTitle": "Warden FAQ",
    "description": "The Warden is a 10-level calling from *The Lord of the Rings Roleplaying* built around Dexterity, Wisdom, martial weapons, travel, tracking, and protecting threatened lands. It uses a d10 Hit Die, gains Shadow-lore and Warded Lands at 1st level, a Fighting Style at 2nd, Extra Attack at 5th, and chooses the Forayer or Hunter Warden Oath at 3rd level.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Warden class in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.warden.how-do-you-play-a-warden": {
    "href": "/faq/warden/how-do-you-play-a-warden",
    "external": false,
    "title": "D&D Portal - How do you play a Warden?",
    "subTitle": "Warden FAQ",
    "description": "Play a Warden by combining a clear weapon style with Wisdom-based awareness and travel expertise. Use Warded Lands aggressively during journeys, remember Shadow-lore when dealing with favoured foes, and use Rumour of the Earth to detect threats before the party walks into them. Forayer rewards ambushes and stealth; Hunter rewards tracking and sustained pressure on chosen prey.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you play a Warden?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.warden.what-ability-scores-are-best-for-a-warden": {
    "href": "/faq/warden/what-ability-scores-are-best-for-a-warden",
    "external": false,
    "title": "D&D Portal - What ability scores are best for a Warden?",
    "subTitle": "Warden FAQ",
    "description": "Dexterity and Wisdom are the Warden's primary abilities. Dexterity supports ranged and finesse weapons, initiative, and common scouting skills, while Wisdom powers the calling's awareness and threat-detection identity. Constitution is a useful third priority for a d10 martial character. Under the multiple-calling rules, Warden requires Wisdom 13.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What ability scores are best for a Warden?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.warden.what-are-the-main-warden-class-features": {
    "href": "/faq/warden/what-are-the-main-warden-class-features",
    "external": false,
    "title": "D&D Portal - What are the main Warden class features?",
    "subTitle": "Warden FAQ",
    "description": "The Warden's main features are Shadow-lore, Warded Lands, Fighting Style, Virtue or Craft choices, a Warden Oath, Rumour of the Earth, Extra Attack, improvements to Shadow-lore and Warded Lands, an additional Oath feature, and Long Stride. The calling progresses to 10th level and specialises through Forayer or Hunter.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Warden class features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.warden.what-subclasses-can-a-warden-choose": {
    "href": "/faq/warden/what-subclasses-can-a-warden-choose",
    "external": false,
    "title": "D&D Portal - What subclasses can a Warden choose?",
    "subTitle": "Warden FAQ",
    "description": "A Warden chooses one of two **Warden Oaths** at 3rd level: **Forayer** or **Hunter**. Forayer specialises in stealth, ambushes, initiative, Sneak Attack, and hiding during combat. Hunter specialises in tracking favoured foes and chooses a Hunter's Prey technique for repeated pressure against dangerous quarry.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What subclasses can a Warden choose?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
