  "internals.faq.classes.how-do-i-choose-a-class-in-dnd": {
    "href": "/faq/classes/how-do-i-choose-a-class-in-dnd",
    "external": false,
    "title": "D&D Portal - How do I choose a class in D&D?",
    "subTitle": "Classes FAQ",
    "description": "Choose a class by starting with the play style and fantasy you want, then compare its primary abilities, combat role, spellcasting or resource complexity, subclass options, and campaign availability. Do not choose only from damage rankings: a class that matches how you want to solve problems will usually be more satisfying than a theoretically stronger class whose normal turn you do not enjoy.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do I choose a class in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.classes.what-is-the-difference-between-dnd-classes-and-subclasses": {
    "href": "/faq/classes/what-is-the-difference-between-dnd-classes-and-subclasses",
    "external": false,
    "title": "D&D Portal - What is the difference between D&D classes and subclasses?",
    "subTitle": "Classes FAQ",
    "description": "A class is the character's main level progression, while a subclass is a specialization inside that class. The class supplies the core chassis—such as Hit Die, proficiencies, spellcasting, resources, and most features—while the subclass adds themed features at specific levels. Different classes use different subclass names, such as Primal Path, Divine Domain, Roguish Archetype, Messenger Path, Shinobi Path, or Fight Club.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the difference between D&D classes and subclasses?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.classes.can-you-have-more-than-one-class-in-dnd": {
    "href": "/faq/classes/can-you-have-more-than-one-class-in-dnd",
    "external": false,
    "title": "D&D Portal - Can you have more than one class in D&D?",
    "subTitle": "Classes FAQ",
    "description": "Yes, if the campaign uses multiclassing rules, a character can take levels in more than one class. Each class keeps its own level-based features and Hit Dice, while proficiency bonus is based on total character level. Multiclassing also has prerequisites and special interaction rules, especially for proficiencies and spell slots. Additional or homebrew D&D Portal classes should only be multiclassed when their own rules define how that works.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "Can you have more than one class in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
