  "internals.faq.rules.what-are-rules-in-dnd": {
    "href": "/faq/rules/what-are-rules-in-dnd",
    "external": false,
    "title": "D&D Portal - What are rules in D&D?",
    "subTitle": "Rules FAQ",
    "description": "Rules in D&D are the procedures used to decide what characters and creatures can do and how uncertain outcomes are resolved. They cover ability checks, saving throws, attacks, movement, spellcasting, damage, conditions, rests, character features and many other systems. The published rules form a baseline, while the Dungeon Master adjudicates situations the rules do not fully specify. D&D Portal can also record clearly labelled campaign-specific rulings without turning those rulings into universal D&D rules.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are rules in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.rules.how-do-dnd-rules-work-during-play": {
    "href": "/faq/rules/how-do-dnd-rules-work-during-play",
    "external": false,
    "title": "D&D Portal - How do D&D rules work during play?",
    "subTitle": "Rules FAQ",
    "description": "During play, the group first describes the situation and the intended action. If the outcome is uncertain, the relevant rule determines what roll or resource is used. The DM applies circumstances such as advantage, disadvantage, cover, distance, difficulty or conditions, then the result changes the fiction. In combat this process is organized into rounds and turns; outside combat it is usually handled more freely.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do D&D rules work during play?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.rules.what-is-the-difference-between-core-optional-and-house-rules": {
    "href": "/faq/rules/what-is-the-difference-between-core-optional-and-house-rules",
    "external": false,
    "title": "D&D Portal - What is the difference between core rules, optional rules, and house rules?",
    "subTitle": "Rules FAQ",
    "description": "Core rules are the normal published procedures a ruleset assumes. Optional or variant rules are published alternatives that a group uses only when the DM or campaign adopts them. House rules are table-created changes or additions. D&D Portal campaign rules are house rules or campaign rulings when they intentionally differ from the published baseline, and they must be labelled as such.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the difference between core rules, optional rules, and house rules?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.rules.who-decides-when-a-dnd-rule-is-unclear": {
    "href": "/faq/rules/who-decides-when-a-dnd-rule-is-unclear",
    "external": false,
    "title": "D&D Portal - Who decides what happens when a D&D rule is unclear?",
    "subTitle": "Rules FAQ",
    "description": "The Dungeon Master adjudicates unclear or uncovered situations at the table. The best approach is to check the specific feature and relevant general rule first, preserve clearly written exceptions, and then let the DM make a ruling where ambiguity remains. A recurring ruling can be documented in D&D Portal as a campaign note, but that does not retroactively make it the published rule.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "Who decides what happens when a D&D rule is unclear?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.rules.how-do-dnd-portal-campaign-notes-affect-the-rules": {
    "href": "/faq/rules/how-do-dnd-portal-campaign-notes-affect-the-rules",
    "external": false,
    "title": "D&D Portal - How do D&D Portal campaign notes affect the rules?",
    "subTitle": "Rules FAQ",
    "description": "Campaign notes apply only to the parties or campaigns they identify. They can clarify, restrict, expand, or replace a published rule for those games, but they remain separate from the general rules explanation. If no campaign override applies, use the normal published rule.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do D&D Portal campaign notes affect the rules?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
