  "internals.faq.species.what-are-species-in-dnd": {
    "href": "/faq/species/what-are-species-in-dnd",
    "external": false,
    "title": "D&D Portal - What are species in D&D?",
    "subTitle": "Species FAQ",
    "description": "A species is one of the major character-origin choices that describes what kind of people or creature your character belongs to and grants a package of game traits. Depending on the source, those traits can include size, speed, senses, languages, ability-score increases or flexible increases, resistances, proficiencies, innate magic, movement abilities, or other special features. D&D Portal uses the term Species, while older 2014 sourcebooks often use the legacy rules term race.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are species in D&D?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.species.how-do-you-choose-a-species-for-your-character": {
    "href": "/faq/species/how-do-you-choose-a-species-for-your-character",
    "external": false,
    "title": "D&D Portal - How do you choose a species for your character?",
    "subTitle": "Species FAQ",
    "description": "Choose a species by checking three things: whether it is available in your campaign, whether its traits support the kind of character you want to play, and whether its story fits the concept you want. You do not need to choose the mathematically strongest pairing. In D&D Portal, availability and campaign notes matter because a published species can still be restricted or modified for a particular party.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you choose a species for your character?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.species.what-abilities-do-dnd-species-give-you": {
    "href": "/faq/species/what-abilities-do-dnd-species-give-you",
    "external": false,
    "title": "D&D Portal - What abilities do D&D species give you?",
    "subTitle": "Species FAQ",
    "description": "Species can grant passive traits, proficiencies, senses, movement options, resistances, languages, innate magic, limited-use actions, and source-specific ability-score increases. The exact package varies by species and publication. For example, the 2014 Human increases every ability score by 1 and gains an extra language; the 2014 Elf gains Dexterity, Darkvision, Keen Senses, Fey Ancestry, Trance and subrace traits; Astral Elf instead uses its Spelljammer trait package including Astral Fire, Starlight Step and Astral Trance.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What abilities do D&D species give you?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.species.does-your-species-affect-your-characters-class": {
    "href": "/faq/species/does-your-species-affect-your-characters-class",
    "external": false,
    "title": "D&D Portal - Does your species affect your character's class?",
    "subTitle": "Species FAQ",
    "description": "Species and class are separate choices, so your species does not normally force you into a particular class. Species traits can make certain class features easier to use or provide useful tools a class lacks, but any permitted species/class combination can be a valid character. Source edition matters because older species may include fixed ability-score increases while later species use more flexible rules.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "Does your species affect your character's class?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.species.what-is-the-best-species-for-a-new-dnd-player": {
    "href": "/faq/species/what-is-the-best-species-for-a-new-dnd-player",
    "external": false,
    "title": "D&D Portal - What is the best species for a new D&D player?",
    "subTitle": "Species FAQ",
    "description": "There is no single best species for a new player. Among the species currently documented here, the standard 2014 Human is mechanically the simplest because its core benefits are passive: +1 to every ability score, Medium size, 30-foot speed, and an extra language. Elf adds several persistent traits and subrace choices, while Astral Elf adds active options such as a cantrip, a limited-use teleport, and flexible proficiencies after trance.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the best species for a new D&D player?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
