  "internals.faq.elf.what-traits-does-a-2014-elf-get": {
    "href": "/faq/elf/what-traits-does-a-2014-elf-get",
    "external": false,
    "title": "D&D Portal - What traits does a 2014 Elf get?",
    "subTitle": "Elf FAQ",
    "description": "The 2014 core Elf traits are +2 Dexterity, Medium size, 30-foot walking speed, 60-foot Darkvision, Keen Senses granting Perception proficiency, Fey Ancestry, Trance, Common, and Elvish. A 2014 Elf then also chooses a subrace that adds further traits.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What traits does a 2014 Elf get?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.elf.how-do-fey-ancestry-and-trance-work-for-a-2014-elf": {
    "href": "/faq/elf/how-do-fey-ancestry-and-trance-work-for-a-2014-elf",
    "external": false,
    "title": "D&D Portal - How do Fey Ancestry and Trance work for a 2014 Elf?",
    "subTitle": "Elf FAQ",
    "description": "Fey Ancestry gives a 2014 Elf advantage on saving throws against being charmed and prevents magic from putting the Elf to sleep. Trance means the Elf does not need normal sleep and can gain the stated resting benefit after four hours of semiconscious meditation. Neither trait makes the Elf immune to every effect that causes unconsciousness.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do Fey Ancestry and Trance work for a 2014 Elf?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.elf.what-is-the-difference-between-elf-and-astral-elf-in-dnd-portal": {
    "href": "/faq/elf/what-is-the-difference-between-elf-and-astral-elf-in-dnd-portal",
    "external": false,
    "title": "D&D Portal - What is the difference between Elf and Astral Elf in D&D Portal?",
    "subTitle": "Elf FAQ",
    "description": "The 2014 Basic Rules Elf and the 2022 Astral Elf from *Spelljammer: Adventures in Space* are separate species rule packages. Astral Elf keeps familiar elven traits such as Darkvision, Fey Ancestry, and Keen Senses, but adds Astral Fire, Starlight Step, and Astral Trance and uses the later flexible ability-score model.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the difference between Elf and Astral Elf in D&D Portal?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.elf.which-classes-work-well-with-a-2014-elf": {
    "href": "/faq/elf/which-classes-work-well-with-a-2014-elf",
    "external": false,
    "title": "D&D Portal - Which classes work well with a 2014 Elf?",
    "subTitle": "Elf FAQ",
    "description": "Any permitted class can work with a 2014 Elf. The fixed +2 Dexterity naturally supports Rogues, Rangers, Monks, Dexterity Fighters and other characters using finesse or ranged weapons, while High Elf and Wood Elf subrace traits can support different directions. The species does not restrict class choice, and the best pairing depends on the character's actual ability scores, subclass and campaign.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "Which classes work well with a 2014 Elf?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
