  "internals.faq.astral-elf.what-traits-does-an-astral-elf-get": {
    "href": "/faq/astral-elf/what-traits-does-an-astral-elf-get",
    "external": false,
    "title": "D&D Portal - What traits does an Astral Elf get?",
    "subTitle": "Astral Elf FAQ",
    "description": "An Astral Elf is a Medium Humanoid that also counts as an elf, has 30-foot walking speed, Darkvision, Fey Ancestry, Keen Senses, Astral Fire, Starlight Step, and Astral Trance. The Spelljammer species uses flexible ability-score increases: +2 to one score and +1 to another, or +1 to three different scores.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What traits does an Astral Elf get?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.astral-elf.how-does-starlight-step-work": {
    "href": "/faq/astral-elf/how-does-starlight-step-work",
    "external": false,
    "title": "D&D Portal - How does Starlight Step work?",
    "subTitle": "Astral Elf FAQ",
    "description": "Starlight Step is a bonus-action species trait that magically teleports an Astral Elf up to 30 feet to an unoccupied space the Elf can see. It is not a spell, uses no spell slot, and can be used a number of times equal to proficiency bonus, with all expended uses returning after a long rest.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Starlight Step work?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.astral-elf.how-do-astral-fire-and-astral-trance-work": {
    "href": "/faq/astral-elf/how-do-astral-fire-and-astral-trance-work",
    "external": false,
    "title": "D&D Portal - How do Astral Fire and Astral Trance work?",
    "subTitle": "Astral Elf FAQ",
    "description": "Astral Fire gives an Astral Elf one cantrip chosen from dancing lights, light, or sacred flame, using Intelligence, Wisdom, or Charisma chosen for that trait. Astral Trance lets the Elf complete a long rest in four hours of conscious meditation and, after finishing it, gain one skill proficiency plus one weapon or tool proficiency until the next long rest.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do Astral Fire and Astral Trance work?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.astral-elf.can-astral-elf-be-used-in-every-dnd-portal-campaign": {
    "href": "/faq/astral-elf/can-astral-elf-be-used-in-every-dnd-portal-campaign",
    "external": false,
    "title": "D&D Portal - Can Astral Elf be used in every D&D Portal campaign?",
    "subTitle": "Astral Elf FAQ",
    "description": "No universal campaign availability should be assumed. Astral Elf is a published Spelljammer species, but publication and campaign permission are separate. Party 1 may use Astral Elf only when the character is connected to that campaign's observatory storyline.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "Can Astral Elf be used in every D&D Portal campaign?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
