  "internals.faq.mastermind.what-is-the-mastermind-roguish-archetype": {
    "href": "/faq/mastermind/what-is-the-mastermind-roguish-archetype",
    "external": false,
    "title": "D&D Portal - What is the Mastermind Roguish Archetype?",
    "subTitle": "Mastermind FAQ",
    "description": "The Mastermind is a social and tactical support Rogue that excels at disguise, languages, reading opponents and using the Help action from range. At Rogue 3, Mastermind adds tactical Help, languages, disguise, and social tools to a character that still advances normally in Sneak Attack, Cunning Action, and the Rogue's defensive features.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Mastermind Roguish Archetype?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.mastermind.what-are-the-main-mastermind-features": {
    "href": "/faq/mastermind/what-are-the-main-mastermind-features",
    "external": false,
    "title": "D&D Portal - What are the main Mastermind features?",
    "subTitle": "Mastermind FAQ",
    "description": "Mastermind is a tactical and social Rogue focused on coordination, disguise, languages, and manipulating other people. Master of Tactics turns Help into a powerful bonus-action support tool, while later features improve social reading, misdirection, and resistance to magical attempts to read or verify the Rogue's thoughts.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Mastermind features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.mastermind.how-do-you-build-and-play-a-mastermind-rogue": {
    "href": "/faq/mastermind/how-do-you-build-and-play-a-mastermind-rogue",
    "external": false,
    "title": "D&D Portal - How do you build and play a Mastermind Rogue?",
    "subTitle": "Mastermind FAQ",
    "description": "Build the Mastermind on top of a normal Dexterity-focused Rogue, then invest in the secondary abilities and skills that support the archetype. Think about allies' turns as part of your own. Master of Tactics can create advantage for a heavy-hitting ally without giving up your action. Outside combat, use languages, disguises, forgery and Expertise to become an organiser, infiltrator or intelligence specialist.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you build and play a Mastermind Rogue?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.mastermind.how-does-mastermind-interact-with-sneak-attack": {
    "href": "/faq/mastermind/how-does-mastermind-interact-with-sneak-attack",
    "external": false,
    "title": "D&D Portal - How does Mastermind interact with Sneak Attack?",
    "subTitle": "Mastermind FAQ",
    "description": "Mastermind does not create a special personal Sneak Attack trigger. Its combat strength is often indirect: the bonus-action Help improves an ally's attack while the Rogue still uses the action for a normal Sneak Attack weapon attack. This makes it a strong cooperative archetype.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Mastermind interact with Sneak Attack?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.mastermind.how-does-master-of-tactics-work": {
    "href": "/faq/mastermind/how-does-master-of-tactics-work",
    "external": false,
    "title": "D&D Portal - How does Master of Tactics work?",
    "subTitle": "Mastermind FAQ",
    "description": "Master of Tactics lets a Mastermind use the Help action as a bonus action. When using Help to aid an ally's attack, the target of that attack can be within 30 feet of you rather than requiring the normal close positioning, provided the feature's visibility and hearing requirements are satisfied.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Master of Tactics work?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
