  "internals.faq.phantom.what-is-the-phantom-roguish-archetype": {
    "href": "/faq/phantom/what-is-the-phantom-roguish-archetype",
    "external": false,
    "title": "D&D Portal - What is the Phantom Roguish Archetype?",
    "subTitle": "Phantom FAQ",
    "description": "The Phantom is a supernatural Rogue connected to the dead, able to borrow skills from spirits, spread Sneak Attack damage through Wails from the Grave and create Soul Trinkets from nearby deaths. Phantom begins at Rogue 3 and adds spirit-based utility and secondary damage on top of the standard Rogue progression rather than replacing its weapon-focused Sneak Attack gameplay.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Phantom Roguish Archetype?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.phantom.what-are-the-main-phantom-features": {
    "href": "/faq/phantom/what-are-the-main-phantom-features",
    "external": false,
    "title": "D&D Portal - What are the main Phantom features?",
    "subTitle": "Phantom FAQ",
    "description": "Phantom gives the Rogue a supernatural connection to the dead. Whispers of the Dead supplies flexible proficiency, Wails from the Grave spreads Sneak Attack damage to another creature, Soul Trinkets turn nearby deaths into defensive and utility resources, and later features add spectral movement and stronger death-themed offense.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Phantom features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.phantom.how-do-you-build-and-play-a-phantom-rogue": {
    "href": "/faq/phantom/how-do-you-build-and-play-a-phantom-rogue",
    "external": false,
    "title": "D&D Portal - How do you build and play a Phantom Rogue?",
    "subTitle": "Phantom FAQ",
    "description": "Build the Phantom on top of a normal Dexterity-focused Rogue, then invest in the secondary abilities and skills that support the archetype. Treat Wails from the Grave as a way to spread pressure when two important enemies are present. Preserve reactions when a Soul Trinket opportunity matters. Outside combat, Whispers of the Dead lets you adapt to the next task after a rest without permanently committing every proficiency choice.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you build and play a Phantom Rogue?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.phantom.how-does-phantom-interact-with-sneak-attack": {
    "href": "/faq/phantom/how-does-phantom-interact-with-sneak-attack",
    "external": false,
    "title": "D&D Portal - How does Phantom interact with Sneak Attack?",
    "subTitle": "Phantom FAQ",
    "description": "Wails from the Grave is triggered by Sneak Attack rather than replacing it. You first deal normal Sneak Attack damage to the creature you hit; the Phantom feature then creates a separate necrotic-damage effect against another eligible creature. Because it is tied to Sneak Attack, reliably landing one qualifying hit remains the core combat goal.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Phantom interact with Sneak Attack?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.phantom.how-do-soul-trinkets-work-for-a-phantom-rogue": {
    "href": "/faq/phantom/how-do-soul-trinkets-work-for-a-phantom-rogue",
    "external": false,
    "title": "D&D Portal - How do Soul Trinkets work for a Phantom Rogue?",
    "subTitle": "Phantom FAQ",
    "description": "From 9th level, a Phantom can use a reaction when a creature dies nearby to create a Soul Trinket, up to a limit based on proficiency bonus. Carrying trinkets grants defensive benefits, and a trinket can be destroyed either to ask the spirit a question or to fuel Wails from the Grave without spending one of its normal daily uses.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do Soul Trinkets work for a Phantom Rogue?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
