  "internals.faq.soulknife.what-is-the-soulknife-roguish-archetype": {
    "href": "/faq/soulknife/what-is-the-soulknife-roguish-archetype",
    "external": false,
    "title": "D&D Portal - What is the Soulknife Roguish Archetype?",
    "subTitle": "Soulknife FAQ",
    "description": "The Soulknife is a psionic Rogue that uses Psionic Energy Dice for skill reliability, telepathy, supernatural movement and attack correction while creating Psychic Blades that leave no ordinary weapon behind. Soulknife starts at Rogue 3, adding psionic dice, telepathy, and Psychic Blades to the normal Rogue progression instead of turning the character into a separate psionic caster.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Soulknife Roguish Archetype?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.soulknife.what-are-the-main-soulknife-features": {
    "href": "/faq/soulknife/what-are-the-main-soulknife-features",
    "external": false,
    "title": "D&D Portal - What are the main Soulknife features?",
    "subTitle": "Soulknife FAQ",
    "description": "Soulknife is a psionic Rogue that fights with manifested Psychic Blades and a pool of Psionic Energy Dice. Psi-Bolstered Knack improves important skill checks, Psychic Whispers provides telepathic coordination, Soul Blades add attack correction and teleportation, and later features provide invisibility and a powerful mind-rending strike.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Soulknife features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.soulknife.how-do-you-build-and-play-a-soulknife-rogue": {
    "href": "/faq/soulknife/how-do-you-build-and-play-a-soulknife-rogue",
    "external": false,
    "title": "D&D Portal - How do you build and play a Soulknife Rogue?",
    "subTitle": "Soulknife FAQ",
    "description": "Build the Soulknife on top of a normal Dexterity-focused Rogue, then invest in the secondary abilities and skills that support the archetype. Use Psi-Bolstered Knack on important proficient checks where the die can turn failure into success, and remember that the die is preserved when the boost still fails. Psychic Blades are excellent when you need concealed, disposable weapons, but magic items and resistance interactions may make a conventional weapon relevant in some campaigns.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you build and play a Soulknife Rogue?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.soulknife.how-does-soulknife-interact-with-sneak-attack": {
    "href": "/faq/soulknife/how-does-soulknife-interact-with-sneak-attack",
    "external": false,
    "title": "D&D Portal - How does Soulknife interact with Sneak Attack?",
    "subTitle": "Soulknife FAQ",
    "description": "Psychic Blades qualify for Sneak Attack because they are finesse weapons. The first blade deals the larger damage die; the bonus-action blade is another opportunity to land Sneak Attack if the first attack missed and Sneak Attack has not yet been applied that turn.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Soulknife interact with Sneak Attack?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.soulknife.how-do-psionic-energy-dice-and-psychic-blades-work": {
    "href": "/faq/soulknife/how-do-psionic-energy-dice-and-psychic-blades-work",
    "external": false,
    "title": "D&D Portal - How do Psionic Energy Dice and Psychic Blades work?",
    "subTitle": "Soulknife FAQ",
    "description": "Soulknife uses two related but separate systems. Psionic Energy Dice fuel abilities such as Psi-Bolstered Knack, Psychic Whispers, Homing Strikes and Psychic Teleportation. Psychic Blades are manifested weapons used through the Attack action; the first blade deals 1d6 psychic damage and can enable a 1d4 bonus-action blade attack. The blades do not normally cost Psionic Energy Dice.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do Psionic Energy Dice and Psychic Blades work?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
