  "internals.faq.swashbuckler.how-does-rakish-audacity-change-sneak-attack": {
    "href": "/faq/swashbuckler/how-does-rakish-audacity-change-sneak-attack",
    "external": false,
    "title": "D&D Portal - How does Rakish Audacity change Sneak Attack?",
    "subTitle": "Swashbuckler FAQ",
    "description": "Rakish Audacity allows a Swashbuckler to Sneak Attack a creature in a clean one-on-one melee situation: you must be within 5 feet of the target, no other creatures can be within 5 feet of you, and you cannot have disadvantage. It also adds your Charisma modifier to initiative. It does not remove the finesse/ranged weapon or once-per-turn Sneak Attack rules.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Rakish Audacity change Sneak Attack?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
