  "internals.faq.thief.what-is-the-thief-roguish-archetype": {
    "href": "/faq/thief/what-is-the-thief-roguish-archetype",
    "external": false,
    "title": "D&D Portal - What is the Thief Roguish Archetype?",
    "subTitle": "Thief FAQ",
    "description": "The Thief is an agility and utility Rogue that expands Cunning Action into fast object and thieves' tool use, climbs efficiently, sneaks reliably and eventually ignores many magic-item restrictions. Thief begins at Rogue 3 and expands object use, climbing, stealth, and magic-item flexibility while keeping the base Rogue's precision damage, skills, mobility, and defensive progression.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Thief Roguish Archetype?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.thief.what-are-the-main-thief-features": {
    "href": "/faq/thief/what-are-the-main-thief-features",
    "external": false,
    "title": "D&D Portal - What are the main Thief features?",
    "subTitle": "Thief FAQ",
    "description": "Thief emphasizes speed, climbing, stealth, object use, and magic-item flexibility. Fast Hands expands Cunning Action into practical item and thieves' tool interactions, Second-Story Work improves climbing and jumping, Supreme Sneak rewards careful movement, Use Magic Device bypasses many item restrictions, and Thief's Reflexes gives an extraordinary first round.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Thief features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.thief.how-do-you-build-and-play-a-thief-rogue": {
    "href": "/faq/thief/how-do-you-build-and-play-a-thief-rogue",
    "external": false,
    "title": "D&D Portal - How do you build and play a Thief Rogue?",
    "subTitle": "Thief FAQ",
    "description": "Build the Thief on top of a normal Dexterity-focused Rogue, then invest in the secondary abilities and skills that support the archetype. Use the environment. The Thief gains the most when there are doors, traps, locks, elevation, objects, equipment and terrain to exploit. Fast Hands can free the normal action for an attack while the bonus action handles a practical interaction that would normally consume an action.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you build and play a Thief Rogue?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.thief.how-does-thief-interact-with-sneak-attack": {
    "href": "/faq/thief/how-does-thief-interact-with-sneak-attack",
    "external": false,
    "title": "D&D Portal - How does Thief interact with Sneak Attack?",
    "subTitle": "Thief FAQ",
    "description": "Thief does not add a new Sneak Attack condition. Its advantage comes from positioning and action economy: climbing, stealth and Fast Hands can help create a strong firing or melee position while leaving the action free for the qualifying Sneak Attack weapon attack.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Thief interact with Sneak Attack?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.thief.what-can-fast-hands-do-in-the-2014-rules": {
    "href": "/faq/thief/what-can-fast-hands-do-in-the-2014-rules",
    "external": false,
    "title": "D&D Portal - What can Fast Hands do in the 2014 rules?",
    "subTitle": "Thief FAQ",
    "description": "Fast Hands expands Cunning Action so the Thief can use a bonus action for a Dexterity (Sleight of Hand) check, thieves' tools to disarm a trap or open a lock, or the 2014 Use an Object action. It does not automatically allow every action involving an object or magic item as a bonus action.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What can Fast Hands do in the 2014 rules?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
