  "internals.faq.path-of-elemental-ninjutsu.what-is-the-path-of-elemental-ninjutsu": {
    "href": "/faq/path-of-elemental-ninjutsu/what-is-the-path-of-elemental-ninjutsu",
    "external": false,
    "title": "D&D Portal - What is the Path of Elemental Ninjutsu?",
    "subTitle": "Path of Elemental Ninjutsu FAQ",
    "description": "The Path of Elemental Ninjutsu is a Shinobi Path built around Nature Techniques, elemental damage and battlefield shaping. It gains Elemental Adept at 3rd level, Secondary Nature at 6th, Elemental Shaping at 10th and Nature Mastery at 14th, while retaining the base Shinobi's Chakra, Fortune Dice, Extra Attack and technique progression.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Path of Elemental Ninjutsu?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.path-of-elemental-ninjutsu.what-are-the-main-path-of-elemental-ninjutsu-features": {
    "href": "/faq/path-of-elemental-ninjutsu/what-are-the-main-path-of-elemental-ninjutsu-features",
    "external": false,
    "title": "D&D Portal - What are the main Path of Elemental Ninjutsu features?",
    "subTitle": "Path of Elemental Ninjutsu FAQ",
    "description": "Its four Path features are Elemental Adept, Secondary Nature, Elemental Shaping and Nature Mastery. Together they add extra Nature Techniques, a second standard Chakra Nature, metamagic-like shaping options for Nature Techniques and strong resistance or immunity penetration at high level.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Path of Elemental Ninjutsu features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.path-of-elemental-ninjutsu.how-do-you-build-and-play-a-path-of-elemental-ninjutsu-shinobi": {
    "href": "/faq/path-of-elemental-ninjutsu/how-do-you-build-and-play-a-path-of-elemental-ninjutsu-shinobi",
    "external": false,
    "title": "D&D Portal - How do you build and play a Path of Elemental Ninjutsu Shinobi?",
    "subTitle": "Path of Elemental Ninjutsu FAQ",
    "description": "Keep Wisdom and Dexterity high, learn Nature Techniques that cover different jobs instead of only raw damage, and use Chakra aggressively when an area, range or resistance interaction can change the encounter. Secondary Nature and Elemental Shaping reward a versatile elemental toolkit more than repeating nearly identical attacks.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you build and play a Path of Elemental Ninjutsu Shinobi?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.path-of-elemental-ninjutsu.how-does-path-of-elemental-ninjutsu-interact-with-chakra-natures-and-techniques": {
    "href": "/faq/path-of-elemental-ninjutsu/how-does-path-of-elemental-ninjutsu-interact-with-chakra-natures-and-techniques",
    "external": false,
    "title": "D&D Portal - How does Path of Elemental Ninjutsu interact with Chakra Natures and Techniques?",
    "subTitle": "Path of Elemental Ninjutsu FAQ",
    "description": "The Path expands access to Nature Techniques rather than replacing the normal technique system. Elemental Adept grants two extra Nature Techniques from a nature already available to you, Secondary Nature adds access to another standard nature and another free technique, and later features modify or discount Nature Techniques specifically.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Path of Elemental Ninjutsu interact with Chakra Natures and Techniques?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.path-of-elemental-ninjutsu.how-does-elemental-shaping-work": {
    "href": "/faq/path-of-elemental-ninjutsu/how-does-elemental-shaping-work",
    "external": false,
    "title": "D&D Portal - How does Elemental Shaping work?",
    "subTitle": "Path of Elemental Ninjutsu FAQ",
    "description": "At 10th level, Elemental Shaping lets you spend 1 additional Chakra Point when activating a Nature Technique to apply one of four modifications: Distant, Expanded, Careful or Piercing. Only one listed modification is applied by this feature to that activation unless another rule explicitly says otherwise.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Elemental Shaping work?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
