  "internals.faq.path-of-genjutsu.what-is-the-path-of-genjutsu": {
    "href": "/faq/path-of-genjutsu/what-is-the-path-of-genjutsu",
    "external": false,
    "title": "D&D Portal - What is the Path of Genjutsu?",
    "subTitle": "Path of Genjutsu FAQ",
    "description": "The Path of Genjutsu is a control-focused Shinobi Path built around illusion, misdirection and mental pressure. It gains Genjutsu Training, Distorted Perception, Persistent Illusion and World of Illusion, allowing the Shinobi to improve Genjutsu access, interfere with enemy attacks, force rerolls against Genjutsu and eventually trap multiple enemies in a shared illusion.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Path of Genjutsu?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.path-of-genjutsu.what-are-the-main-path-of-genjutsu-features": {
    "href": "/faq/path-of-genjutsu/what-are-the-main-path-of-genjutsu-features",
    "external": false,
    "title": "D&D Portal - What are the main Path of Genjutsu features?",
    "subTitle": "Path of Genjutsu FAQ",
    "description": "The Path gains Genjutsu Training at 3rd level, Distorted Perception at 6th, Persistent Illusion at 10th and World of Illusion at 14th. These features expand Genjutsu technique access, disrupt attacks, improve the reliability and persistence of illusions and provide a powerful area-control effect.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Path of Genjutsu features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.path-of-genjutsu.how-do-you-build-and-play-a-path-of-genjutsu-shinobi": {
    "href": "/faq/path-of-genjutsu/how-do-you-build-and-play-a-path-of-genjutsu-shinobi",
    "external": false,
    "title": "D&D Portal - How do you build and play a Path of Genjutsu Shinobi?",
    "subTitle": "Path of Genjutsu FAQ",
    "description": "Prioritize Wisdom for Technique Save DC and Dexterity for the Shinobi chassis, choose Genjutsu techniques that solve different control problems, and protect concentration. The Path is strongest when it denies enemy actions, creates misses and changes positioning rather than trying to compete with a pure damage build.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you build and play a Path of Genjutsu Shinobi?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.path-of-genjutsu.how-do-genjutsu-techniques-interact-with-persistent-illusion": {
    "href": "/faq/path-of-genjutsu/how-do-genjutsu-techniques-interact-with-persistent-illusion",
    "external": false,
    "title": "D&D Portal - How do Genjutsu techniques interact with Persistent Illusion?",
    "subTitle": "Path of Genjutsu FAQ",
    "description": "Persistent Illusion improves Genjutsu in two ways: once on each of your turns, after a creature succeeds on a saving throw against one of your Genjutsu techniques, you may spend 1 Chakra Point to force a reroll; and if you lose concentration on a Genjutsu technique because you failed the concentration save, that technique remains active until the end of your next turn.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do Genjutsu techniques interact with Persistent Illusion?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.path-of-genjutsu.how-does-world-of-illusion-work": {
    "href": "/faq/path-of-genjutsu/how-does-world-of-illusion-work",
    "external": false,
    "title": "D&D Portal - How does World of Illusion work?",
    "subTitle": "Path of Genjutsu FAQ",
    "description": "World of Illusion is the 14th-level Genjutsu Path feature. As an action, choose a point within 60 feet; each chosen creature in a 20-foot-radius sphere makes a Wisdom save against your Technique Save DC. On a failure, it is charmed and incapacitated for up to 1 minute while you concentrate. Affected creatures repeat the save at the end of each turn and whenever they take damage. You can use the feature once per long rest.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does World of Illusion work?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
