  "internals.faq.path-of-the-medical-shinobi.what-is-the-path-of-the-medical-shinobi": {
    "href": "/faq/path-of-the-medical-shinobi/what-is-the-path-of-the-medical-shinobi",
    "external": false,
    "title": "D&D Portal - What is the Path of the Medical Shinobi?",
    "subTitle": "Path of the Medical Shinobi FAQ",
    "description": "The Path of the Medical Shinobi is a support and precision-melee Shinobi Path built around healing, condition removal and biological chakra control. It gains Medical Training, Chakra Scalpel, Cellular Restoration and Regenerative Seal, allowing the character to heal more efficiently, fight with Wisdom-powered unarmed strikes and remove dangerous conditions.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Path of the Medical Shinobi?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.path-of-the-medical-shinobi.what-are-the-main-path-of-the-medical-shinobi-features": {
    "href": "/faq/path-of-the-medical-shinobi/what-are-the-main-path-of-the-medical-shinobi-features",
    "external": false,
    "title": "D&D Portal - What are the main Path of the Medical Shinobi features?",
    "subTitle": "Path of the Medical Shinobi FAQ",
    "description": "The Path gains Medical Training at 3rd level, Chakra Scalpel at 6th, Cellular Restoration at 10th and Regenerative Seal at 14th. Together they strengthen First Aid, add a Wisdom-based melee mode, remove serious conditions and provide a prepared emergency heal.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Path of the Medical Shinobi features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.path-of-the-medical-shinobi.how-do-you-build-and-play-a-medical-shinobi": {
    "href": "/faq/path-of-the-medical-shinobi/how-do-you-build-and-play-a-medical-shinobi",
    "external": false,
    "title": "D&D Portal - How do you build and play a Medical Shinobi?",
    "subTitle": "Path of the Medical Shinobi FAQ",
    "description": "Prioritize Wisdom, keep Dexterity and Constitution healthy, and treat healing as one part of the character rather than the only job. Use First Aid and condition removal when they prevent an ally from losing meaningful turns, while Chakra Scalpel lets you contribute direct melee pressure without abandoning the support role.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you build and play a Medical Shinobi?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.path-of-the-medical-shinobi.how-do-first-aid-technique-and-medical-training-work-together": {
    "href": "/faq/path-of-the-medical-shinobi/how-do-first-aid-technique-and-medical-training-work-together",
    "external": false,
    "title": "D&D Portal - How do First Aid Technique and Medical Training work together?",
    "subTitle": "Path of the Medical Shinobi FAQ",
    "description": "Medical Training gives you First Aid Technique if you do not already know it and makes it a stronger repeatable support tool. A creature can regain hit points from your First Aid Technique twice per short or long rest instead of once, and whenever one of your Shinobi techniques restores hit points, the target also gains temporary hit points equal to your proficiency bonus.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do First Aid Technique and Medical Training work together?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.path-of-the-medical-shinobi.how-do-chakra-scalpel-cellular-restoration-and-regenerative-seal-differ": {
    "href": "/faq/path-of-the-medical-shinobi/how-do-chakra-scalpel-cellular-restoration-and-regenerative-seal-differ",
    "external": false,
    "title": "D&D Portal - How do Chakra Scalpel, Cellular Restoration and Regenerative Seal differ?",
    "subTitle": "Path of the Medical Shinobi FAQ",
    "description": "Chakra Scalpel is an offensive 1-minute melee mode, Cellular Restoration is an action-based condition-removal tool fueled by 3 Chakra Points, and Regenerative Seal is a long-rest preparation that later triggers a large emergency heal plus condition removal. They solve different problems and should not be treated as interchangeable healing buttons.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do Chakra Scalpel, Cellular Restoration and Regenerative Seal differ?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
