  "internals.faq.battlerager.what-is-the-battlerager": {
    "href": "/faq/battlerager/what-is-the-battlerager",
    "external": false,
    "title": "D&D Portal - What is the Path of the Battlerager?",
    "subTitle": "Path of the Battlerager FAQ",
    "description": "The Path of the Battlerager is a spiked-armor Barbarian path built around close-range aggression, grappling, temporary hit points and punishing creatures that stay beside the Barbarian. Choosing Battlerager at Barbarian 3 adds its spiked-armour brawler identity to the normal Rage, Reckless Attack, Extra Attack, Fast Movement, Brutal Critical, Relentless Rage, and other core Barbarian progression.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Path of the Battlerager?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.battlerager.what-are-the-main-battlerager-features": {
    "href": "/faq/battlerager/what-are-the-main-battlerager-features",
    "external": false,
    "title": "D&D Portal - What are the main Path of the Battlerager features?",
    "subTitle": "Path of the Battlerager FAQ",
    "description": "Battlerager is a close-quarters Barbarian built around spiked armor. Battlerager Armor adds a bonus-action spike attack and grapple damage, Reckless Abandon converts Reckless Attack into temporary hit points, Battlerager Charge improves pursuit, and Spiked Retribution punishes nearby enemies that hit you.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Path of the Battlerager features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.battlerager.how-do-you-build-and-play-a-battlerager-barbarian": {
    "href": "/faq/battlerager/how-do-you-build-and-play-a-battlerager-barbarian",
    "external": false,
    "title": "D&D Portal - How do you build and play a Battlerager Barbarian?",
    "subTitle": "Path of the Battlerager FAQ",
    "description": "Strength is the primary attack and grapple ability, Constitution supports hit points and Reckless Abandon, and Dexterity is useful only up to what the chosen medium armor can benefit from. The subclass is tightly tied to spiked armor, so the campaign must actually make that equipment available. In play, Fight in close quarters, use Reckless Attack when the temporary hit points meaningfully offset the risk, grapple when holding an enemy in place helps the party, and use Battlerager Charge to reach enemies without giving up the Attack action.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you build and play a Battlerager Barbarian?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.battlerager.how-does-battlerager-interact-with-rage": {
    "href": "/faq/battlerager/how-does-battlerager-interact-with-rage",
    "external": false,
    "title": "D&D Portal - How does Path of the Battlerager interact with Rage?",
    "subTitle": "Path of the Battlerager FAQ",
    "description": "Battlerager's signature armor attack, Charge and Spiked Retribution all depend on Rage. Reckless Abandon also requires Reckless Attack while raging. The path is therefore especially resource-dependent on having Rage available in the encounters that matter.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Path of the Battlerager interact with Rage?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.battlerager.do-you-have-to-be-a-dwarf-to-play-a-battlerager": {
    "href": "/faq/battlerager/do-you-have-to-be-a-dwarf-to-play-a-battlerager",
    "external": false,
    "title": "D&D Portal - Do you have to be a dwarf to play a Battlerager?",
    "subTitle": "Path of the Battlerager FAQ",
    "description": "In its original *Sword Coast Adventurer's Guide* presentation, the Path of the Battlerager is a dwarven tradition and is restricted to dwarves unless the DM lifts that setting-specific restriction. The restriction is part of that publication context rather than a universal rule for every campaign setting.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "Do you have to be a dwarf to play a Battlerager?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
