  "internals.faq.beast.what-is-the-beast": {
    "href": "/faq/beast/what-is-the-beast",
    "external": false,
    "title": "D&D Portal - What is the Path of the Beast?",
    "subTitle": "Path of the Beast FAQ",
    "description": "The Path of the Beast is a transformation-focused Barbarian path that manifests natural weapons while raging and later gains supernatural movement, contagious fury and pack-hunting support. Choosing Beast at Barbarian 3 adds its transforming natural-weapon identity to the normal Rage, Reckless Attack, Extra Attack, Fast Movement, Brutal Critical, Relentless Rage, and other core Barbarian progression.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Path of the Beast?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.beast.what-are-the-main-beast-features": {
    "href": "/faq/beast/what-are-the-main-beast-features",
    "external": false,
    "title": "D&D Portal - What are the main Path of the Beast features?",
    "subTitle": "Path of the Beast FAQ",
    "description": "Path of the Beast transforms the Barbarian's body during Rage. Form of the Beast provides a Bite, Claws, or Tail mode for each Rage, Bestial Soul adds magical attacks and adaptable movement, Infectious Fury turns natural-weapon hits into control or psychic damage, and Call the Hunt empowers the Barbarian alongside nearby allies.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Path of the Beast features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.beast.how-do-you-build-and-play-a-beast-barbarian": {
    "href": "/faq/beast/how-do-you-build-and-play-a-beast-barbarian",
    "external": false,
    "title": "D&D Portal - How do you build and play a Beast Barbarian?",
    "subTitle": "Path of the Beast FAQ",
    "description": "Strength remains the natural attack ability because the path is designed to work with Rage and Reckless Attack. Constitution remains important for durability and several Barbarian features. The path does not need a separate casting ability. In play, Choose the Beast form for the encounter: Claws favor repeated attacks, Tail favors reach and defense, and Bite favors sustain when the healing condition can apply. At higher levels, use Bestial Soul to solve movement problems and Infectious Fury on priority enemies rather than trivial targets.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you build and play a Beast Barbarian?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.beast.how-does-beast-interact-with-rage": {
    "href": "/faq/beast/how-does-beast-interact-with-rage",
    "external": false,
    "title": "D&D Portal - How does Path of the Beast interact with Rage?",
    "subTitle": "Path of the Beast FAQ",
    "description": "Form of the Beast appears when Rage begins, and Infectious Fury requires a natural-weapon hit while raging. Call the Hunt also begins when you Rage. Rage is therefore the switch that activates most of the path's supernatural combat identity.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Path of the Beast interact with Rage?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.beast.how-do-the-path-of-the-beast-natural-weapons-work": {
    "href": "/faq/beast/how-do-the-path-of-the-beast-natural-weapons-work",
    "external": false,
    "title": "D&D Portal - How do the Path of the Beast natural weapons work?",
    "subTitle": "Path of the Beast FAQ",
    "description": "Whenever you enter Rage, choose Bite, Claws or Tail. The chosen natural weapon counts as a simple melee weapon for you, uses Strength naturally with the Barbarian chassis, and lasts until the Rage ends. Bite supports self-healing, Claws can create an additional claw attack, and Tail provides reach plus a defensive reaction.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do the Path of the Beast natural weapons work?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
