  "internals.faq.berserker.what-is-the-berserker": {
    "href": "/faq/berserker/what-is-the-berserker",
    "external": false,
    "title": "D&D Portal - What is the Path of the Berserker?",
    "subTitle": "Path of the Berserker FAQ",
    "description": "The Path of the Berserker is the classic 2014 offensive Barbarian path that can enter a Frenzy for additional weapon attacks and later becomes highly resistant to fear and charm while raging. Choosing Berserker at Barbarian 3 adds its all-out offensive identity to the normal Rage, Reckless Attack, Extra Attack, Fast Movement, Brutal Critical, Relentless Rage, and other core Barbarian progression.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Path of the Berserker?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.berserker.what-are-the-main-berserker-features": {
    "href": "/faq/berserker/what-are-the-main-berserker-features",
    "external": false,
    "title": "D&D Portal - What are the main Path of the Berserker features?",
    "subTitle": "Path of the Berserker FAQ",
    "description": "The 2014 Berserker is the Barbarian path of relentless offense. Frenzy can add a melee attack every turn after the Rage begins at the cost of exhaustion when the Rage ends, Mindless Rage shuts down charm and fear while raging, Intimidating Presence adds a fear option, and Retaliation punishes nearby creatures for damaging you.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Path of the Berserker features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.berserker.how-do-you-build-and-play-a-berserker-barbarian": {
    "href": "/faq/berserker/how-do-you-build-and-play-a-berserker-barbarian",
    "external": false,
    "title": "D&D Portal - How do you build and play a Berserker Barbarian?",
    "subTitle": "Path of the Berserker FAQ",
    "description": "Strength and Constitution remain the main abilities. Charisma affects Intimidating Presence, but increasing Charisma purely for that feature competes with the Barbarian's core physical priorities. The subclass does not require Charisma to function well in its main offensive role. In play, use normal Rage for ordinary encounters and Frenzy when the extra bonus-action attacks justify the exhaustion cost. Retaliation rewards staying in melee with dangerous enemies, while Mindless Rage makes the subclass particularly reliable against fear and charm effects.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you build and play a Berserker Barbarian?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.berserker.how-does-berserker-interact-with-rage": {
    "href": "/faq/berserker/how-does-berserker-interact-with-rage",
    "external": false,
    "title": "D&D Portal - How does Path of the Berserker interact with Rage?",
    "subTitle": "Path of the Berserker FAQ",
    "description": "Frenzy is an upgraded Rage choice, Mindless Rage only functions while raging, and the subclass's main identity is therefore strongly tied to Rage availability. Retaliation itself does not require Rage in the 2014 feature text, but it naturally fits the close-range Rage play style.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Path of the Berserker interact with Rage?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.berserker.how-does-frenzy-and-exhaustion-work-for-a-2014-berserker": {
    "href": "/faq/berserker/how-does-frenzy-and-exhaustion-work-for-a-2014-berserker",
    "external": false,
    "title": "D&D Portal - How does Frenzy and exhaustion work for a 2014 Berserker?",
    "subTitle": "Path of the Berserker FAQ",
    "description": "When a 2014 Berserker enters Rage, it can choose to make that Rage a Frenzy. During the Frenzy, it can make one melee weapon attack as a bonus action on each turn after the turn the Frenzy begins. When the Rage ends, the Berserker gains one level of exhaustion. The 2024 version uses different mechanics.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Frenzy and exhaustion work for a 2014 Berserker?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
