  "internals.faq.storm-herald.what-is-the-storm-herald": {
    "href": "/faq/storm-herald/what-is-the-storm-herald",
    "external": false,
    "title": "D&D Portal - What is the Path of the Storm Herald?",
    "subTitle": "Path of the Storm Herald FAQ",
    "description": "The Path of the Storm Herald is an elemental-aura Barbarian path that chooses Desert, Sea or Tundra and turns Rage into a persistent storm that can deal damage, grant temporary hit points or protect nearby allies. Choosing Storm Herald at Barbarian 3 adds its elemental-aura identity to the normal Rage, Reckless Attack, Extra Attack, Fast Movement, Brutal Critical, Relentless Rage, and other core Barbarian progression.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Path of the Storm Herald?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.storm-herald.what-are-the-main-storm-herald-features": {
    "href": "/faq/storm-herald/what-are-the-main-storm-herald-features",
    "external": false,
    "title": "D&D Portal - What are the main Path of the Storm Herald features?",
    "subTitle": "Path of the Storm Herald FAQ",
    "description": "Storm Herald surrounds the raging Barbarian with a Desert, Sea, or Tundra aura. Storm Aura provides repeatable elemental offense or temporary hit points, Storm Soul adds matching resistance and environmental benefits, Shielding Storm extends that resistance to allies, and Raging Storm adds a final control or retaliation effect tied to the chosen environment.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Path of the Storm Herald features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.storm-herald.how-do-you-build-and-play-a-storm-herald-barbarian": {
    "href": "/faq/storm-herald/how-do-you-build-and-play-a-storm-herald-barbarian",
    "external": false,
    "title": "D&D Portal - How do you build and play a Storm Herald Barbarian?",
    "subTitle": "Path of the Storm Herald FAQ",
    "description": "Strength and Constitution remain the main Barbarian abilities. Constitution also determines the saving throw DC used by Storm Aura effects that require one, making it especially valuable on Sea and later environment-based control features. In play, Choose the storm environment for the campaign and party composition, then remember that the aura competes for your bonus action. Desert is aggressive area pressure, Sea is focused lightning damage, and Tundra is repeatable temporary-hit-point support.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you build and play a Storm Herald Barbarian?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.storm-herald.how-does-storm-herald-interact-with-rage": {
    "href": "/faq/storm-herald/how-does-storm-herald-interact-with-rage",
    "external": false,
    "title": "D&D Portal - How does Path of the Storm Herald interact with Rage?",
    "subTitle": "Path of the Storm Herald FAQ",
    "description": "Storm Aura only exists while you are raging, Shielding Storm only functions through that aura, and Raging Storm is likewise tied to Rage. The path is one of the clearest examples of a subclass that converts Rage into a supernatural battlefield effect.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Path of the Storm Herald interact with Rage?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.storm-herald.how-does-storm-aura-work": {
    "href": "/faq/storm-herald/how-does-storm-aura-work",
    "external": false,
    "title": "D&D Portal - How does Storm Aura work?",
    "subTitle": "Path of the Storm Herald FAQ",
    "description": "When you choose Path of the Storm Herald, select Desert, Sea or Tundra. While raging, you emanate a 10-foot Storm Aura. As a bonus action on each of your turns, including the turn your Rage begins when your action economy allows, you can activate the aura's current effect. The chosen environment can be changed when you gain a Barbarian level.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Storm Aura work?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
