  "internals.faq.totem-warrior.what-is-the-totem-warrior": {
    "href": "/faq/totem-warrior/what-is-the-totem-warrior",
    "external": false,
    "title": "D&D Portal - What is the Path of the Totem Warrior?",
    "subTitle": "Path of the Totem Warrior FAQ",
    "description": "The Path of the Totem Warrior is a spirit-guided Barbarian path that chooses animal totems at several subclass levels, mixing defensive, mobility and party-support benefits around Rage and wilderness spirituality. Choosing Totem Warrior at Barbarian 3 adds its spirit-guided identity to the normal Rage, Reckless Attack, Extra Attack, Fast Movement, Brutal Critical, Relentless Rage, and other core Barbarian progression.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Path of the Totem Warrior?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.totem-warrior.what-are-the-main-totem-warrior-features": {
    "href": "/faq/totem-warrior/what-are-the-main-totem-warrior-features",
    "external": false,
    "title": "D&D Portal - What are the main Path of the Totem Warrior features?",
    "subTitle": "Path of the Totem Warrior FAQ",
    "description": "The 2014 Totem Warrior combines spiritual rituals with modular animal totems. Totem Spirit changes how Rage works in combat, Aspect of the Beast adds exploration or physical utility, Spirit Walker provides nature divination, and Totemic Attunement adds another high-level combat benefit. Bear, Eagle, and Wolf choices can be mixed across the progression.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Path of the Totem Warrior features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.totem-warrior.how-do-you-build-and-play-a-totem-warrior-barbarian": {
    "href": "/faq/totem-warrior/how-do-you-build-and-play-a-totem-warrior-barbarian",
    "external": false,
    "title": "D&D Portal - How do you build and play a Totem Warrior Barbarian?",
    "subTitle": "Path of the Totem Warrior FAQ",
    "description": "Strength and Constitution remain the main combat abilities. Wisdom can support Survival, Perception and the path's spiritual identity but is not required to power the primary Totem Spirit combat features. In play, Choose totems according to the role you want at each feature level. Bear at 3rd level is exceptional for durability, Eagle favors mobility, and Wolf rewards a melee-heavy party. The path also contributes outside combat through rituals and Aspect of the Beast.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you build and play a Totem Warrior Barbarian?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.totem-warrior.how-does-totem-warrior-interact-with-rage": {
    "href": "/faq/totem-warrior/how-does-totem-warrior-interact-with-rage",
    "external": false,
    "title": "D&D Portal - How does Path of the Totem Warrior interact with Rage?",
    "subTitle": "Path of the Totem Warrior FAQ",
    "description": "The 3rd-level Totem Spirit and 14th-level Totemic Attunement combat benefits are primarily designed around Rage. The ritual and exploration features remain useful outside Rage, giving the path more non-combat identity than many Barbarian subclasses.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Path of the Totem Warrior interact with Rage?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.totem-warrior.do-all-of-your-totem-warrior-animal-choices-have-to-match": {
    "href": "/faq/totem-warrior/do-all-of-your-totem-warrior-animal-choices-have-to-match",
    "external": false,
    "title": "D&D Portal - Do all of your Totem Warrior animal choices have to match?",
    "subTitle": "Path of the Totem Warrior FAQ",
    "description": "No. In the 2014 Path of the Totem Warrior, the animal chosen for Aspect of the Beast at 6th level and Totemic Attunement at 14th level can be the same as or different from the animal chosen for Totem Spirit at 3rd level. You can mix Bear, Eagle and Wolf benefits across the subclass.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "Do all of your Totem Warrior animal choices have to match?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
