  "internals.faq.wild-magic.what-is-the-wild-magic": {
    "href": "/faq/wild-magic/what-is-the-wild-magic",
    "external": false,
    "title": "D&D Portal - What is the Path of Wild Magic?",
    "subTitle": "Path of Wild Magic FAQ",
    "description": "The Path of Wild Magic is a magical-chaos Barbarian path that detects nearby magic, triggers a random Wild Surge whenever Rage begins and later manipulates d20 rolls, spell slots and the surge table itself. Choosing Wild Magic at Barbarian 3 adds its chaotic-magical identity to the normal Rage, Reckless Attack, Extra Attack, Fast Movement, Brutal Critical, Relentless Rage, and other core Barbarian progression.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Path of Wild Magic?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.wild-magic.what-are-the-main-wild-magic-features": {
    "href": "/faq/wild-magic/what-are-the-main-wild-magic-features",
    "external": false,
    "title": "D&D Portal - What are the main Path of Wild Magic features?",
    "subTitle": "Path of Wild Magic FAQ",
    "description": "Path of Wild Magic makes each Rage produce a temporary magical effect. Magic Awareness detects nearby magic, Wild Surge rolls a random combat effect when Rage begins, Bolstering Magic supports attacks, checks, or spell-slot recovery, Unstable Backlash can replace a surge after you are hurt or fail a save, and Controlled Surge gives you much more control over the table.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Path of Wild Magic features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.wild-magic.how-do-you-build-and-play-a-wild-magic-barbarian": {
    "href": "/faq/wild-magic/how-do-you-build-and-play-a-wild-magic-barbarian",
    "external": false,
    "title": "D&D Portal - How do you build and play a Path of Wild Magic Barbarian?",
    "subTitle": "Path of Wild Magic FAQ",
    "description": "Strength and Constitution remain the primary combat abilities. The path's magical features do not introduce a conventional spellcasting ability. Constitution still matters heavily because you are a Barbarian expected to remain in dangerous positions. In play, Enter Rage when a Wild Surge can matter, learn what every table result enables, and adapt your turn rather than forcing the same routine after every roll. Bolstering Magic is valuable outside combat and can support either martial allies or spellcasters depending on the chosen mode.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you build and play a Path of Wild Magic Barbarian?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.wild-magic.how-does-wild-magic-interact-with-rage": {
    "href": "/faq/wild-magic/how-does-wild-magic-interact-with-rage",
    "external": false,
    "title": "D&D Portal - How does Path of Wild Magic interact with Rage?",
    "subTitle": "Path of Wild Magic FAQ",
    "description": "Wild Surge happens when Rage begins, Unstable Backlash only functions while raging, and Controlled Surge modifies future surge rolls. The path is therefore built around Rage repeatedly generating a temporary magical combat identity.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How does Path of Wild Magic interact with Rage?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.wild-magic.are-wild-surge-effects-spells-and-can-they-work-while-raging": {
    "href": "/faq/wild-magic/are-wild-surge-effects-spells-and-can-they-work-while-raging",
    "external": false,
    "title": "D&D Portal - Are Wild Surge effects spells, and can they work while raging?",
    "subTitle": "Path of Wild Magic FAQ",
    "description": "Wild Surge effects are subclass features, not spells unless a specific effect explicitly says otherwise. Entering Rage triggers the table directly, so the normal 2014 rule preventing spellcasting or concentration while raging does not automatically shut off Wild Surge effects. Follow the exact duration and action wording of the rolled result.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "Are Wild Surge effects spells, and can they work while raging?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
