  "internals.faq.life-domain.what-is-the-life-domain": {
    "href": "/faq/life-domain/what-is-the-life-domain",
    "external": false,
    "title": "D&D Portal - What is the Life Domain?",
    "subTitle": "Life Domain FAQ",
    "description": "The Life Domain is the 2014 Cleric subclass focused most directly on healing, protection, restoration and preserving life. It grants heavy armor, improves healing spells through Disciple of Life, adds the Preserve Life Channel Divinity, heals the Cleric when healing others, adds radiant Divine Strike damage and eventually maximizes the healing dice of spells through Supreme Healing.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Life Domain?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.life-domain.what-are-the-main-life-domain-features": {
    "href": "/faq/life-domain/what-are-the-main-life-domain-features",
    "external": false,
    "title": "D&D Portal - What are the main Life Domain features?",
    "subTitle": "Life Domain FAQ",
    "description": "The main 2014 Life Domain features are Bonus Proficiency and Disciple of Life at 1st level, Channel Divinity: Preserve Life at 2nd, Blessed Healer at 6th, Divine Strike at 8th and Supreme Healing at 17th. The Domain also grants ten always-prepared Domain Spells across Cleric levels 1 through 9.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Life Domain features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.life-domain.how-do-you-build-and-play-a-life-domain-cleric": {
    "href": "/faq/life-domain/how-do-you-build-and-play-a-life-domain-cleric",
    "external": false,
    "title": "D&D Portal - How do you build and play a Life Domain Cleric?",
    "subTitle": "Life Domain FAQ",
    "description": "Keep Wisdom high for Cleric spellcasting, use heavy armor when it suits the build, and treat healing as one part of a full Cleric toolkit rather than spending every action restoring hit points. Life Domain is especially efficient at bringing injured allies back into a safe range while still contributing through concentration spells, control, radiant damage and ordinary Cleric support.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you build and play a Life Domain Cleric?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.life-domain.how-do-life-domain-spells-work": {
    "href": "/faq/life-domain/how-do-life-domain-spells-work",
    "external": false,
    "title": "D&D Portal - How do Life Domain spells work?",
    "subTitle": "Life Domain FAQ",
    "description": "Life Domain Spells are added automatically at Cleric levels 1, 3, 5, 7 and 9. Once you gain one, it is always prepared, does not count against the number of Cleric spells you can prepare each day, and counts as a Cleric spell for you even if it would not normally appear on the Cleric spell list.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do Life Domain spells work?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.life-domain.how-do-disciple-of-life-blessed-healer-and-supreme-healing-work-together": {
    "href": "/faq/life-domain/how-do-disciple-of-life-blessed-healer-and-supreme-healing-work-together",
    "external": false,
    "title": "D&D Portal - How do Disciple of Life, Blessed Healer and Supreme Healing work together?",
    "subTitle": "Life Domain FAQ",
    "description": "Disciple of Life increases the hit points restored to the spell's target by 2 + the spell's level. Blessed Healer separately restores hit points to you when that qualifying healing spell targets another creature. At 17th level, Supreme Healing maximizes the spell's healing dice. These are separate features and can all matter on the same qualifying healing spell.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do Disciple of Life, Blessed Healer and Supreme Healing work together?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
