  "internals.faq.death-domain.what-is-the-death-domain": {
    "href": "/faq/death-domain/what-is-the-death-domain",
    "external": false,
    "title": "D&D Portal - What is the Death Domain?",
    "subTitle": "Death Domain FAQ",
    "description": "The Death Domain is a 2014 Dungeon Master's Guide Cleric subclass focused on necromancy, necrotic damage and supernatural death magic. It grants martial weapon proficiency, Reaper for splitting eligible necromancy cantrips between nearby targets, Channel Divinity: Touch of Death for burst necrotic damage, resistance penetration through Inescapable Destruction, necrotic Divine Strike and Improved Reaper for higher-level necromancy spells.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What is the Death Domain?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.death-domain.what-are-the-main-death-domain-features": {
    "href": "/faq/death-domain/what-are-the-main-death-domain-features",
    "external": false,
    "title": "D&D Portal - What are the main Death Domain features?",
    "subTitle": "Death Domain FAQ",
    "description": "The main 2014 Death Domain features are martial weapon proficiency and Reaper at 1st level, Channel Divinity: Touch of Death at 2nd, Inescapable Destruction at 6th, necrotic Divine Strike at 8th and Improved Reaper at 17th. The Domain also supplies an always-prepared necromancy-focused spell list.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "What are the main Death Domain features?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.death-domain.how-do-you-build-and-play-a-death-domain-cleric": {
    "href": "/faq/death-domain/how-do-you-build-and-play-a-death-domain-cleric",
    "external": false,
    "title": "D&D Portal - How do you build and play a Death Domain Cleric?",
    "subTitle": "Death Domain FAQ",
    "description": "Keep Wisdom high for Cleric spellcasting, decide whether the martial weapon proficiency will actually be part of the build, and use Reaper or Improved Reaper when two valid enemies are close enough to share a necromancy effect. Touch of Death rewards landing a melee attack, but the subclass remains a full Cleric and should not be played as though every turn must be a weapon attack.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do you build and play a Death Domain Cleric?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.death-domain.how-do-reaper-and-improved-reaper-work": {
    "href": "/faq/death-domain/how-do-reaper-and-improved-reaper-work",
    "external": false,
    "title": "D&D Portal - How do Reaper and Improved Reaper work?",
    "subTitle": "Death Domain FAQ",
    "description": "Reaper affects eligible necromancy cantrips that normally target only one creature, while Improved Reaper extends the concept to necromancy spells of 1st through 5th level. In both cases, a second creature can be targeted only when it is also within the spell's range and close enough to the first target. These features do not turn area spells or already-multi-target spells into larger effects.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do Reaper and Improved Reaper work?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
  "internals.faq.death-domain.how-do-touch-of-death-and-inescapable-destruction-work-together": {
    "href": "/faq/death-domain/how-do-touch-of-death-and-inescapable-destruction-work-together",
    "external": false,
    "title": "D&D Portal - How do Touch of Death and Inescapable Destruction work together?",
    "subTitle": "Death Domain FAQ",
    "description": "Touch of Death spends Channel Divinity after a melee attack hits to deal extra necrotic damage equal to 5 + twice your Cleric level. From 6th level, Inescapable Destruction causes necrotic damage from your Cleric spells and Channel Divinity to ignore resistance to necrotic damage, so Touch of Death can bypass necrotic resistance. It does not turn necrotic immunity into resistance.",
    "img": {
      "href": "/branding/dnd-portal-icon.svg",
      "alt": "The D&D Portal Wiki logo representing an internal page\n\t\t\t\twithin the website."
    },
    "label": "How do Touch of Death and Inescapable Destruction work together?",
    "navigation": {
      "parent": "internals.utility.faq"
    }
  },
